package com.streamchat;

import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import lombok.extern.slf4j.Slf4j;

/**
 * Lifecycle, status tracking and reconnect backoff shared by every source.
 *
 * <p>Subclasses implement {@link #doConnect()} and {@link #doStop()} and call
 * {@link #onConnected()} / {@link #onDisconnected(String)} / {@link #onFatal(String)}. Everything
 * to do with <em>when</em> to retry lives here so the three platforms cannot drift apart.
 */
@Slf4j
public abstract class AbstractChatSource implements ChatSource
{
	private static final long BASE_BACKOFF_MS = 2_000L;
	private static final long MAX_BACKOFF_MS = 300_000L;

	protected final ScheduledExecutorService executor;
	protected final ChatSink sink;

	private final AtomicBoolean running = new AtomicBoolean();
	private volatile Future<?> pending;
	private volatile SourceStatus status = SourceStatus.DISABLED;
	private volatile String statusDetail = "";
	private volatile int consecutiveFailures;

	protected AbstractChatSource(ScheduledExecutorService executor, ChatSink sink)
	{
		this.executor = executor;
		this.sink = sink;
	}

	@Override
	public final void start()
	{
		if (!running.compareAndSet(false, true))
		{
			return;
		}

		consecutiveFailures = 0;
		setStatus(SourceStatus.CONNECTING, "connecting");
		schedule(0L);
	}

	@Override
	public final void stop()
	{
		if (!running.compareAndSet(true, false))
		{
			return;
		}

		final Future<?> p = pending;
		if (p != null)
		{
			p.cancel(false);
			pending = null;
		}

		try
		{
			doStop();
		}
		catch (Exception ex)
		{
			log.debug("[{}] error during stop", platform(), ex);
		}

		setStatus(SourceStatus.DISABLED, "stopped");
	}

	/** True between {@link #start()} and {@link #stop()}. Subclasses must not act once this is false. */
	protected final boolean isRunning()
	{
		return running.get();
	}

	@Override
	public final SourceStatus status()
	{
		return status;
	}

	@Override
	public final String statusDetail()
	{
		return statusDetail;
	}

	/**
	 * Open the connection, or start the poll loop. Called on the executor. Throwing, or calling
	 * {@link #onDisconnected(String)} later, both schedule a retry.
	 */
	protected abstract void doConnect() throws Exception;

	/** Release sockets/timers. Called at most once per {@link #start()}, and never concurrently with it. */
	protected abstract void doStop();

	/** Report a working connection. Resets the backoff. */
	protected final void onConnected()
	{
		consecutiveFailures = 0;
		setStatus(SourceStatus.CONNECTED, "connected");
	}

	/** Report a recoverable failure. Schedules a retry with backoff. */
	protected final void onDisconnected(String reason)
	{
		if (!isRunning())
		{
			return;
		}

		final long delay = nextBackoffMs();
		setStatus(SourceStatus.CONNECTING, reason + "; retrying in " + (delay / 1000) + "s");
		log.debug("[{}] disconnected: {} (retry in {}ms)", platform(), reason, delay);

		try
		{
			doStop();
		}
		catch (Exception ex)
		{
			log.debug("[{}] error cleaning up before retry", platform(), ex);
		}

		schedule(delay);
	}

	/**
	 * Report a failure that retrying will not fix -- a rejected API key, a channel that does not
	 * exist. Stops trying and leaves the reason visible to the user.
	 */
	protected final void onFatal(String reason)
	{
		log.warn("[{}] giving up: {}", platform(), reason);
		running.set(false);

		final Future<?> p = pending;
		if (p != null)
		{
			p.cancel(false);
			pending = null;
		}

		try
		{
			doStop();
		}
		catch (Exception ex)
		{
			log.debug("[{}] error during fatal stop", platform(), ex);
		}

		setStatus(SourceStatus.FAILED, reason);
	}

	private void schedule(long delayMs)
	{
		pending = executor.schedule(() ->
		{
			if (!isRunning())
			{
				return;
			}

			try
			{
				doConnect();
			}
			catch (Exception ex)
			{
				log.debug("[{}] connect failed", platform(), ex);
				onDisconnected(describe(ex));
			}
		}, delayMs, TimeUnit.MILLISECONDS);
	}

	/**
	 * Exponential backoff capped at five minutes, with +/-20% jitter so that a client watching
	 * several channels does not reconnect to all of them in lockstep after an outage.
	 */
	private long nextBackoffMs()
	{
		final int failures = Math.min(consecutiveFailures++, 8);
		final long base = Math.min(BASE_BACKOFF_MS << failures, MAX_BACKOFF_MS);
		final double jitter = 0.8d + (ThreadLocalRandom.current().nextDouble() * 0.4d);
		return (long) (base * jitter);
	}

	private void setStatus(SourceStatus newStatus, String detail)
	{
		this.status = newStatus;
		this.statusDetail = detail == null ? "" : detail;
		sink.onStatus(platform(), newStatus, this.statusDetail);
	}

	private static String describe(Exception ex)
	{
		final String msg = ex.getMessage();
		return msg == null || msg.isEmpty() ? ex.getClass().getSimpleName() : msg;
	}
}

package com.streamchat;

import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.util.ImageUtil;

/**
 * Registers the per-platform chat icons and hands back their {@code <img=n>} indices.
 *
 * <p>Chat icons are appended to the client's shared mod-icon array and there is no way to remove
 * one, so registration happens exactly once per client session even if the plugin is toggled off
 * and on again. This class is a singleton so that flag survives a restart of the plugin.
 */
@Slf4j
@Singleton
public class ChatIcons
{
	private final ChatIconManager chatIconManager;
	private final Map<StreamPlatform, Integer> iconIds = new EnumMap<>(StreamPlatform.class);

	/** The same artwork, kept for the overlay, which draws with Java2D rather than chat markup. */
	private final Map<StreamPlatform, BufferedImage> images = new EnumMap<>(StreamPlatform.class);
	private boolean loaded;

	@Inject
	private ChatIcons(ChatIconManager chatIconManager)
	{
		this.chatIconManager = chatIconManager;
	}

	/** Loads and registers the icons. Must be called on the client thread. */
	public void load()
	{
		if (loaded)
		{
			return;
		}
		loaded = true;

		for (StreamPlatform platform : StreamPlatform.values())
		{
			final BufferedImage image = ImageUtil.loadImageResource(ChatIcons.class, platform.getIconResource());
			if (image == null)
			{
				log.warn("missing icon resource {}", platform.getIconResource());
				continue;
			}

			images.put(platform, image);
			iconIds.put(platform, chatIconManager.registerChatIcon(image));
		}
	}

	/**
	 * Loads just the artwork, with no client involvement.
	 *
	 * <p>The overlay can draw before the client has booted far enough to register chat icons, so it
	 * must not depend on {@link #load()} having run.
	 */
	@Nullable
	public BufferedImage image(StreamPlatform platform)
	{
		BufferedImage image = images.get(platform);
		if (image == null)
		{
			image = ImageUtil.loadImageResource(ChatIcons.class, platform.getIconResource());
			if (image != null)
			{
				images.put(platform, image);
			}
		}
		return image;
	}

	/**
	 * The index to use in an {@code <img=n>} tag, or -1 when the icon is not usable yet.
	 *
	 * <p>Indices are invalidated whenever the client restarts its game state and are reassigned on
	 * the login screen, so this has to be read at render time rather than cached.
	 */
	public int index(StreamPlatform platform)
	{
		final Integer id = iconIds.get(platform);
		return id == null ? -1 : chatIconManager.chatIconIndex(id);
	}
}

package com.streamchat;

/**
 * Where a {@link ChatSource} delivers its output.
 *
 * <p>Implementations must be thread-safe: sources call these from OkHttp dispatcher threads and
 * from the plugin's scheduled executor, never from the client thread.
 */
public interface ChatSink
{
	void onMessage(StreamChatMessage message);

	void onStatus(StreamPlatform platform, SourceStatus status, String detail);
}

package com.streamchat;

/**
 * A live chat feed for one platform.
 *
 * <p>{@link #start()} and {@link #stop()} are idempotent and safe to call from any thread. A source
 * owns its own reconnection: once started it keeps trying until stopped or until it hits an error
 * that retrying cannot fix.
 */
public interface ChatSource
{
	StreamPlatform platform();

	void start();

	void stop();

	SourceStatus status();

	/** Human-readable detail for the current status, e.g. an error message. Never null. */
	String statusDetail();
}

