/** Sound played when a stream event lands. */
@Getter
@RequiredArgsConstructor
public enum EventSound
{
	NONE("None", -1),
	DINGALING("Ding", SoundEffectID.GE_ADD_OFFER_DINGALING),
	COIN_TINKLE("Coins", SoundEffectID.GE_COIN_TINKLE),
	PLOP("Plop", SoundEffectID.GE_INCREMENT_PLOP),
	BOOP("Boop", SoundEffectID.UI_BOOP),
	TELEPORT("Teleport", SoundEffectID.TELEPORT_VWOOP),
	COLLECT("Collect", SoundEffectID.GE_COLLECT_BLOOP);

	private final String displayName;
	private final int soundId;

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.streamchat;

import lombok.RequiredArgsConstructor;

/** Which events are worth reacting to, as opposed to merely showing. */
@RequiredArgsConstructor
public enum EventTrigger
{
	ALL("Every event"),
	SUBS_AND_GIFTS("Subs, gifts and raids"),
	SUBS_ONLY("Subs only");

	private final String displayName;

	public boolean matches(StreamEventType type)
	{
		if (type == null)
		{
			return false;
		}

		switch (this)
		{
			case SUBS_ONLY:
				return type == StreamEventType.SUBSCRIPTION;
			case SUBS_AND_GIFTS:
				return type == StreamEventType.SUBSCRIPTION
					|| type == StreamEventType.GIFT
					|| type == StreamEventType.RAID;
			default:
				return true;
		}
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.streamchat;

import java.awt.Color;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.util.Text;

/**
 * Buffers incoming messages and meters them into the chatbox and/or the on-screen panel.
 *
 * <p>Sources push from network threads; {@link #flush()} drains on the client thread once per game
 * tick. Everything between those two points exists to stop a busy stream from making the game
 * unusable: filtering, de-duplication, a bounded queue that drops the <em>oldest</em> messages so
 * the chatbox stays live rather than falling minutes behind, and a per-tick print budget.
 */
@Slf4j
@Singleton
public class MessageRouter implements ChatSink
{
	/** How many message ids to remember for de-duplication. */
	private static final int DEDUPE_HISTORY = 512;

	/** Minimum gap between "n messages skipped" notices, in game ticks. */
	private static final int DROP_NOTICE_INTERVAL_TICKS = 25;

	/**
	 * How long a message may sit in the queue before it is no longer worth printing.
	 *
	 * <p>This is what stops a backlog dumping into the chatbox all at once. Game ticks only fire
	 * while logged in, so {@link #flush()} does not run at the login screen, during a hop, or on a
	 * disconnect -- while the sources keep receiving. Without an age cap, everything buffered up
	 * during that time arrives in a burst the moment ticks resume. Discarding it matches what the
	 * queue bound already does for a fast chat: stay live rather than fall behind.
	 */
	private static final long MAX_MESSAGE_AGE_MS = 30_000L;

	private final Client client;
	private final ChatMessageManager chatMessageManager;
	private final ChatIcons icons;
	private final StreamChatConfig config;
	private final StreamChatOverlay overlay;
	private final EventReactions reactions;

	private final Object lock = new Object();
	private final Deque<Queued> pending = new ArrayDeque<>();

	/** A message plus the moment it arrived, so {@link #flush()} can tell how stale it is. */
	static final class Queued
	{
		final StreamChatMessage message;
		final long receivedAtMs;

		Queued(StreamChatMessage message, long receivedAtMs)
		{
			this.message = message;
			this.receivedAtMs = receivedAtMs;
		}
	}

	/** Bounded LRU of recently seen message ids. Guarded by {@link #lock}. */
	private final Map<String, Boolean> seen = new LinkedHashMap<String, Boolean>(64, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<String, Boolean> eldest)
		{
			return size() > DEDUPE_HISTORY;
		}
	};

	private final Map<StreamPlatform, SourceStatus> statuses = new ConcurrentHashMap<>();
	private final Map<StreamPlatform, String> statusDetails = new ConcurrentHashMap<>();

	private int droppedSinceNotice;
	private int ticksSinceNotice;

	@Inject
	private MessageRouter(Client client, ChatMessageManager chatMessageManager, ChatIcons icons,
		StreamChatConfig config, StreamChatOverlay overlay, EventReactions reactions)
	{
		this.client = client;
		this.chatMessageManager = chatMessageManager;
		this.icons = icons;
		this.config = config;
		this.overlay = overlay;
		this.reactions = reactions;
	}

	@Override
	public void onMessage(StreamChatMessage message)
	{
		if (isFiltered(message))
		{
			return;
		}

		synchronized (lock)
		{
			final String key = message.getPlatform().name() + '�' + message.getId();
			if (seen.put(key, Boolean.TRUE) != null)
			{
				// Already shown. Reconnects replay recent history on some platforms.
				return;
			}

			final int cap = Math.max(1, config.queueSize());
			while (pending.size() >= cap)
			{
				pending.pollFirst();
				++droppedSinceNotice;
			}

			pending.addLast(new Queued(message, System.currentTimeMillis()));
		}
	}

	@Override
	public void onStatus(StreamPlatform platform, SourceStatus status, String detail)
	{
		statuses.put(platform, status);
		statusDetails.put(platform, detail == null ? "" : detail);
	}

	public SourceStatus statusOf(StreamPlatform platform)
	{
		return statuses.getOrDefault(platform, SourceStatus.DISABLED);
	}

	public String statusDetailOf(StreamPlatform platform)
	{
		return statusDetails.getOrDefault(platform, "");
	}

	/** Forgets buffered messages and connection state. Called when the plugin stops. */
	public void reset()
	{
		synchronized (lock)
		{
			pending.clear();
			seen.clear();
			droppedSinceNotice = 0;
			ticksSinceNotice = 0;
		}

		statuses.clear();
		statusDetails.clear();
		overlay.clear();
	}

	/** Prints up to the per-tick budget. Must be called on the client thread. */
	public void flush()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			// Nothing to print into. Anything arriving now ages out via MAX_MESSAGE_AGE_MS rather
			// than waiting to be dumped in one burst when ticks resume.
			return;
		}

		final int budget = Math.max(1, config.maxMessagesPerTick());
		final List<StreamChatMessage> batch = new ArrayList<>(budget);
		final int dropped;

		synchronized (lock)
		{
			// Drop stale entries first, and without a budget: rationing this to a couple per tick
			// would take half a minute to work through a full queue, which is the burst we are
			// trying to avoid. Discarded silently, since a gap you were not present for is not
			// something worth reporting.
			purgeStale(pending, System.currentTimeMillis(), MAX_MESSAGE_AGE_MS);

			for (int i = 0; i < budget; i++)
			{
				final Queued queued = pending.pollFirst();
				if (queued == null)
				{
					break;
				}
				batch.add(queued.message);
			}

			++ticksSinceNotice;
			if (droppedSinceNotice > 0 && ticksSinceNotice >= DROP_NOTICE_INTERVAL_TICKS)
			{
				dropped = droppedSinceNotice;
				droppedSinceNotice = 0;
				ticksSinceNotice = 0;
			}
			else
			{
				dropped = 0;
			}
		}

		final DisplayMode mode = config.displayMode();
		for (StreamChatMessage msg : batch)
		{
			if (mode.isChatbox())
			{
				print(msg);
			}
			if (mode.isOverlay())
			{
				overlay.add(msg);
			}
			if (msg.isEvent())
			{
				// Fired here rather than on arrival, so a reaction lines up with the message
				// appearing instead of firing early while it is still queued.
				reactions.fire(msg);
			}
		}

		if (dropped > 0 && config.announceDropped() && mode.isChatbox())
		{
			printRaw(new ChatMessageBuilder()
				.append(Color.GRAY, "(" + dropped + " stream message" + (dropped == 1 ? "" : "s") + " skipped)")
				.build());
		}
	}

	/**
	 * Removes entries from the head that are older than {@code maxAgeMs}, returning how many went.
	 *
	 * <p>The queue is FIFO and arrival times only increase, so the first entry still young enough
	 * ends the scan.
	 */
	static int purgeStale(Deque<Queued> queue, long nowMs, long maxAgeMs)
	{
		int removed = 0;
		for (Queued head; (head = queue.peekFirst()) != null && nowMs - head.receivedAtMs > maxAgeMs; )
		{
			queue.pollFirst();
			++removed;
		}
		return removed;
	}

	private void print(StreamChatMessage msg)
	{
		final ChatMessageBuilder builder = new ChatMessageBuilder();

		if (config.showIcon())
		{
			final int iconIndex = icons.index(msg.getPlatform());
			if (iconIndex >= 0)
			{
				builder.img(iconIndex);
				builder.append(" ");
			}
			else
			{
				// Icons are unavailable until the client has built its mod-icon array. Fall back to
				// a text tag rather than printing an unattributed line.
				builder.append(msg.getPlatform().getDefaultAuthorColor(),
					"[" + msg.getPlatform().getDisplayName() + "] ");
			}
		}

		if (config.showChannel() && !msg.getChannel().isEmpty())
		{
			final String channel = ChatText.clean(msg.getChannel(), 32);
			if (!channel.isEmpty())
			{
				builder.append(Color.GRAY, "[" + Text.escapeJagex(channel) + "] ");
			}
		}

		final String author = ChatText.clean(msg.getAuthor(), 32);
		final String body = ChatText.clean(msg.getMessage(), config.maxMessageLength());

		if (body.isEmpty())
		{
			// Everything was unrenderable -- an emoji-only message, typically.
			return;
		}

		final boolean highlight = msg.isEvent() && config.highlightEvents();

		if (!author.isEmpty())
		{
			final Color nameColor = config.colorAuthors()
				? readable(msg.getAuthorColor(), msg.getPlatform())
				: msg.getPlatform().getDefaultAuthorColor();

			// append(Color, String) does not escape, so the author is escaped explicitly here.
			builder.append(nameColor, Text.escapeJagex(author));
			builder.append(": ");
		}

		// append(String) escapes via Text.escapeJagex; the colour overload does not, so an event
		// line is escaped explicitly before it is coloured.
		if (highlight)
		{
			builder.append(config.eventColor(), Text.escapeJagex(body));
		}
		else
		{
			builder.append(body);
		}

		printRaw(builder.build());
	}

	private void printRaw(String value)
	{
		final ChatTarget target = config.chatTarget();

		chatMessageManager.queue(QueuedMessage.builder()
			.type(target.getMessageType())
			.value(value)
			.sender(target.isShowsSender() ? "Stream" : null)
			.build());
	}

	/**
	 * Keeps author colours legible. Platforms let users pick near-black names that vanish against
	 * the chatbox, so anything too dark is lifted towards the platform's colour.
	 */
	static Color readable(Color color, StreamPlatform platform)
	{
		if (color == null)
		{
			return platform.getDefaultAuthorColor();
		}

		// Rec. 601 luma, matching how the eye weights the channels.
		final int luma = (color.getRed() * 299 + color.getGreen() * 587 + color.getBlue() * 114) / 1000;
		if (luma >= 80)
		{
			return color;
		}

		// Brighten rather than discard, so distinct users keep distinct colours.
		return new Color(
			Math.min(255, color.getRed() + 90),
			Math.min(255, color.getGreen() + 90),
			Math.min(255, color.getBlue() + 90));
	}

	private boolean isFiltered(StreamChatMessage msg)
	{
		final String body = msg.getMessage();
		if (body == null || body.trim().isEmpty())
		{
			return true;
		}

		if (msg.isEvent() && !config.showEvents())
		{
			return true;
		}

		// Events are never emote-only in practice, but never hide one on this basis regardless.
		if (msg.isEmoteOnly() && !msg.isEvent() && config.hideEmoteOnly())
		{
			return true;
		}

		if (config.hideCommands())
		{
			final String trimmed = body.trim();
			final char first = trimmed.charAt(0);
			if (first == '!' || first == '?')
			{
				return true;
			}
		}

		final String author = msg.getAuthor() == null ? "" : msg.getAuthor().toLowerCase(Locale.ROOT);
		if (!author.isEmpty())
		{
			for (String blocked : csvLower(config.blockedUsers()))
			{
				if (author.equals(blocked))
				{
					return true;
				}
			}
		}

		final String lowerBody = body.toLowerCase(Locale.ROOT);
		for (String word : csvLower(config.blockedWords()))
		{
			if (lowerBody.contains(word))
			{
				return true;
			}
		}

		return false;
	}

	private static Set<String> csvLower(String csv)
	{
		final Set<String> out = new java.util.LinkedHashSet<>();
		for (String part : Text.fromCSV(csv))
		{
			final String trimmed = part.trim().toLowerCase(Locale.ROOT);
			if (!trimmed.isEmpty())
			{
				out.add(trimmed);
			}
		}
		return out;
	}
}

package com.streamchat;

import java.awt.Font;
import javax.annotation.Nullable;
import lombok.RequiredArgsConstructor;
import net.runelite.client.ui.FontManager;

/** Font choice for the on-screen panel. */
@RequiredArgsConstructor
public enum OverlayFont
{
	/** Whatever the overlay renderer is already using. */
	DEFAULT("Client default"),
	SMALL("Small"),
	REGULAR("Regular"),
	BOLD("Bold");

	private final String displayName;

	/** The font to draw with, or null to leave the graphics context alone. */
	@Nullable
	public Font font()
	{
		switch (this)
		{
			case SMALL:
				return FontManager.getRunescapeSmallFont();
			case REGULAR:
				return FontManager.getRunescapeFont();
			case BOLD:
				return FontManager.getRunescapeBoldFont();
			default:
				return null;
		}
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.streamchat;

/** Connection state of a single {@link ChatSource}, surfaced to the user via the !streamchat command. */
public enum SourceStatus
{
	/** Not configured, or turned off in config. */
	DISABLED,
	/** Connecting, or waiting out a reconnect backoff. */
	CONNECTING,
	/** Receiving messages. */
	CONNECTED,
	/** Stopped after an error that retrying will not fix (bad credentials, bad channel). */
	FAILED
}

