		description = "Comma separated. Any message containing one of these is hidden. Case insensitive.",
		position = 6,
		section = filterSection
	)
	default String blockedWords()
	{
		return "";
	}
}

package com.streamchat;

import java.awt.Color;
import javax.annotation.Nullable;
import lombok.Builder;
import lombok.Value;

/**
 * A single chat message, normalised across every platform.
 *
 * <p>All fields are raw, untrusted, remote text. Escaping and truncation happen in
 * {@link MessageRouter} immediately before the message reaches the chatbox -- never in the
 * sources -- so there is exactly one place that has to be right.
 */
@Value
@Builder
public class StreamChatMessage
{
	StreamPlatform platform;

	/** The channel/room this arrived from, for display when more than one is configured. */
	String channel;

	String author;

	String message;

	/** Author name colour supplied by the platform, or null to use the platform default. */
	@Nullable
	Color authorColor;

	/**
	 * Platform-assigned message id, used for de-duplication. Falls back to a synthetic id when the
	 * platform does not supply one.
	 */
	String id;

	/** Set when this is a notable event (a sub, raid, donation) rather than an ordinary line. */
	@Nullable
	StreamEventType eventType;

	/**
	 * True when the message carries no words of its own -- only emotes.
	 *
	 * <p>Determined per-platform from what the platform actually tells us about emote positions,
	 * not guessed from the text, so it never hides a real message.
	 */
	boolean emoteOnly;

	public boolean isEvent()
	{
		return eventType != null;
	}
}

package com.streamchat;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws recent stream chat as a movable on-screen panel, for people who would rather not have it
 * in the chatbox at all.
 *
 * <p>Text here is cleaned but <em>not</em> escaped: escaping exists to neutralise the game's chat
 * markup, and this draws with Java2D, where {@code <lt>} would simply appear as those characters.
 * {@link ChatText#clean} still runs, so the font cannot be handed anything it cannot render.
 */
@Singleton
public class StreamChatOverlay extends Overlay
{
	private static final int PADDING = 4;
	private static final int ICON_SIZE = 11;
	private static final int ICON_GAP = 3;
	private static final int LINE_GAP = 2;
	private static final Color BORDER_COLOR = new Color(0, 0, 0, 160);

	private final StreamChatConfig config;
	private final ChatIcons icons;

	/** Newest last. Access is confined to the client thread: appended on flush, read on render. */
	private final Deque<StreamChatMessage> recent = new ArrayDeque<>();

	@Inject
	private StreamChatOverlay(StreamChatConfig config, ChatIcons icons)
	{
		this.config = config;
		this.icons = icons;

		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setMovable(true);
		setResizable(true);
		setSnappable(true);
	}

	void add(StreamChatMessage message)
	{
		recent.addLast(message);
		trim();
	}

	void clear()
	{
		recent.clear();
	}

	private void trim()
	{
		final int max = Math.max(1, config.overlayLines());
		while (recent.size() > max)
		{
			recent.pollFirst();
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (recent.isEmpty())
		{
			return null;
		}

		trim();

		final Font font = config.overlayFont().font();
		if (font != null)
		{
			graphics.setFont(font);
		}

		// On resize RuneLite stores BOTH dimensions here, so honouring only the width would throw
		// away a dragged height on the very next frame.
		final Dimension preferred = getPreferredSize();
		final int width = preferred != null && preferred.width > 0
			? preferred.width
			: Math.max(120, config.overlayWidth());
		final int fixedHeight = preferred != null ? preferred.height : 0;

		final FontMetrics metrics = graphics.getFontMetrics();
		final boolean showIcon = config.showIcon();
		final int lineHeight = metrics.getHeight() + LINE_GAP;

		int textWidth = width - (PADDING * 2);
		if (showIcon)
		{
			textWidth -= ICON_SIZE + ICON_GAP;
		}
		textWidth = Math.max(40, textWidth);

		// Lay out newest-first so that a fixed height can stop as soon as the box is full, then
		// flip back to reading order for drawing.
		final List<Row> rows = new ArrayList<>();
		int contentHeight = 0;
		final int budget = fixedHeight > 0 ? fixedHeight - (PADDING * 2) + LINE_GAP : Integer.MAX_VALUE;

		final List<StreamChatMessage> newestFirst = new ArrayList<>(recent);
		for (int i = newestFirst.size() - 1; i >= 0; i--)
		{
			final StreamChatMessage message = newestFirst.get(i);

			final String author = ChatText.clean(message.getAuthor(), 32);
			final String body = ChatText.clean(message.getMessage(), config.maxMessageLength());
			if (body.isEmpty())
			{
				continue;
			}

			final String text = author.isEmpty() ? body : author + ": " + body;
			final Row row = new Row(message, author, wrap(text, metrics, textWidth));
			final int rowHeight = row.lines.size() * lineHeight;

			if (!rows.isEmpty() && contentHeight + rowHeight > budget)
			{
				// The panel is full; older messages scroll off the top.
				break;
			}

			rows.add(0, row);
			contentHeight += rowHeight;
		}

		if (rows.isEmpty())
		{
			return null;
		}

		final int height = fixedHeight > 0 ? fixedHeight : contentHeight + (PADDING * 2) - LINE_GAP;

		final Color background = config.overlayBackgroundColor();
		if (background.getAlpha() > 0)
		{
			graphics.setColor(background);
			graphics.fillRect(0, 0, width, height);
		}

		if (config.overlayBorder())
		{
			// Fixed colour rather than one derived from the background, which is invisible when
			// the background is transparent -- the default.
			graphics.setColor(BORDER_COLOR);
			graphics.drawRect(0, 0, width - 1, height - 1);
		}

		// Anchor to the bottom so the newest message sits at the bottom edge, the way a chat window
		// behaves, rather than leaving the gap there.
		int y = PADDING + metrics.getAscent();
		if (fixedHeight > 0)
		{
			y = Math.max(y, height - PADDING + LINE_GAP - contentHeight + metrics.getAscent());
		}

		final Color textColor = config.overlayTextColor();
		final boolean shadow = config.overlayShadow();
		final Rectangle clip = graphics.getClipBounds();
		graphics.clipRect(0, 0, width, height);

		for (Row row : rows)
		{
			int x = PADDING;

			if (showIcon)
			{
				final BufferedImage icon = icons.image(row.message.getPlatform());
				if (icon != null)
				{
					// Sit the icon on the text baseline rather than the line box, so it lines up
					// with the glyphs instead of floating.
					graphics.drawImage(icon, x, y - icon.getHeight() + 1, null);
				}
				x += ICON_SIZE + ICON_GAP;
			}

			final Color authorColor = config.colorAuthors()
				? MessageRouter.readable(row.message.getAuthorColor(), row.message.getPlatform())
				: row.message.getPlatform().getDefaultAuthorColor();

			for (int i = 0; i < row.lines.size(); i++)
			{
				final String line = row.lines.get(i);

				if (i == 0 && !row.author.isEmpty())
				{
					final String prefix = row.author + ":";
					draw(graphics, prefix, x, y, authorColor, shadow);

					final int offset = metrics.stringWidth(prefix + " ");
					final int from = Math.min(line.length(), prefix.length() + 1);
					draw(graphics, line.substring(from), x + offset, y, textColor, shadow);
				}
				else
				{
					draw(graphics, line, x, y, textColor, shadow);
				}

				y += lineHeight;
			}
		}

		graphics.setClip(clip);

		return new Dimension(width, height);
	}

	private static void draw(Graphics2D graphics, String text, int x, int y, Color color, boolean shadow)
	{
		if (shadow)
		{
			graphics.setColor(Color.BLACK);
			graphics.drawString(text, x + 1, y + 1);
		}
		graphics.setColor(color);
		graphics.drawString(text, x, y);
	}

	/** Greedy word wrap, falling back to a hard break for a single word wider than the panel. */
	static List<String> wrap(String text, FontMetrics metrics, int maxWidth)
	{
		final List<String> lines = new ArrayList<>();
		final StringBuilder line = new StringBuilder();

		for (String word : text.split(" "))
		{
			if (word.isEmpty())
			{
				continue;
			}

			final String candidate = line.length() == 0 ? word : line + " " + word;
			if (metrics.stringWidth(candidate) <= maxWidth)
			{
				line.setLength(0);
				line.append(candidate);
				continue;
			}

			if (line.length() > 0)
			{
				lines.add(line.toString());
				line.setLength(0);
			}

			// A word too long to fit on its own line has to be split mid-word.
			String rest = word;
			while (metrics.stringWidth(rest) > maxWidth && rest.length() > 1)
			{
				int cut = rest.length();
				while (cut > 1 && metrics.stringWidth(rest.substring(0, cut)) > maxWidth)
				{
					--cut;
				}
				lines.add(rest.substring(0, cut));
				rest = rest.substring(cut);
			}
			line.append(rest);
		}

		if (line.length() > 0)
		{
			lines.add(line.toString());
		}

		return lines;
	}

	private static final class Row
	{
		final StreamChatMessage message;
		final String author;
		final List<String> lines;

		Row(StreamChatMessage message, String author, List<String> lines)
		{
			this.message = message;
			this.author = author;
			this.lines = lines;
		}
	}
}

package com.streamchat;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.streamchat.kick.KickChatSource;
import com.streamchat.twitch.TwitchChatSource;
import com.streamchat.youtube.YouTubeChatSource;
import com.streamchat.youtube.YouTubeTarget;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.ThreadFactory;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;
import okhttp3.OkHttpClient;

@PluginDescriptor(
	name = "Stream Chat",
	description = "Shows live Twitch, YouTube and Kick chat in the game chatbox with source icons",
	tags = {"stream", "twitch", "youtube", "kick", "chat", "streaming", "live"}
)
@Slf4j
public class StreamChatPlugin extends Plugin
{
	private static final String STATUS_COMMAND = "streamchat";

	/** Config edits arrive as the user types; wait for them to settle before reconnecting. */
	private static final long CONFIG_DEBOUNCE_MS = 1_000L;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private StreamChatConfig config;

	@Inject
	private MessageRouter router;

	@Inject
	private ChatIcons icons;

	@Inject
	private StreamChatOverlay overlay;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private Gson gson;

	private final Map<StreamPlatform, ChatSource> sources = new EnumMap<>(StreamPlatform.class);

	/**
	 * The plugin owns its executor rather than borrowing RuneLite's shared one: the YouTube source
	 * makes blocking HTTP calls on it, and a slow response should never hold up another plugin's
	 * scheduled work.
	 */
	private ScheduledExecutorService executor;
	private ScheduledFuture<?> pendingRebuild;

	@Provides
	StreamChatConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(StreamChatConfig.class);
	}

	@Override
	protected void startUp()
	{
		final ThreadFactory threadFactory = r ->
		{
			final Thread t = new Thread(r, "stream-chat");
			t.setDaemon(true);
			return t;
		};
		executor = Executors.newSingleThreadScheduledExecutor(threadFactory);

		overlayManager.add(overlay);

		clientThread.invoke(this::loadIconsIfReady);
		rebuildSources();
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);

		if (pendingRebuild != null)
		{
			pendingRebuild.cancel(false);
			pendingRebuild = null;
		}

		for (ChatSource source : sources.values())
		{
			source.stop();
		}
		sources.clear();

		if (executor != null)
		{
			executor.shutdownNow();
			executor = null;
		}

		router.reset();
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		router.flush();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.LOGGED_IN)
		{
			loadIconsIfReady();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!StreamChatConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		final String key = event.getKey();
		// Display and filter options take effect on the next message with no reconnect needed.
		if (!key.startsWith("twitch") && !key.startsWith("youtube") && !key.startsWith("kick"))
		{
			return;
		}

		if (executor == null)
		{
			return;
		}

		if (pendingRebuild != null)
		{
			pendingRebuild.cancel(false);
		}

		pendingRebuild = executor.schedule(this::rebuildSources, CONFIG_DEBOUNCE_MS, TimeUnit.MILLISECONDS);
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		if (!STATUS_COMMAND.equalsIgnoreCase(event.getCommand()))
		{
			return;
		}

		printStatus();
	}

	private void loadIconsIfReady()
	{
		// createIndexedSprite needs a booted client, so wait for the login screen at the earliest.
		if (client.getGameState().getState() >= GameState.LOGIN_SCREEN.getState())
		{
			icons.load();
		}
	}

	/**
	 * Stops every source and starts the ones that are enabled and configured. Called on the plugin
	 * executor after config settles, so it must not touch client state.
	 */
	private synchronized void rebuildSources()
	{
		for (ChatSource source : sources.values())
		{
			source.stop();
		}
		sources.clear();

		final ScheduledExecutorService exec = executor;
		if (exec == null)
		{
			return;
		}

		if (config.twitchEnabled())
		{
			final List<String> channels = channelList(config.twitchChannels());
			if (!channels.isEmpty())
			{
				sources.put(StreamPlatform.TWITCH, new TwitchChatSource(
					exec, router, okHttpClient, channels));
			}
		}

		if (config.youtubeEnabled())
		{
			final YouTubeTarget target = YouTubeTarget.parse(config.youtubeTarget());
			if (target == null)
			{
				router.onStatus(StreamPlatform.YOUTUBE, SourceStatus.FAILED,
					config.youtubeTarget().trim().isEmpty()
						? "no video or channel configured"
						: "could not understand the video/channel setting");
			}
			else if (config.youtubeApiKey().trim().isEmpty())
			{
				router.onStatus(StreamPlatform.YOUTUBE, SourceStatus.FAILED, "no API key configured");
			}
			else
			{
				sources.put(StreamPlatform.YOUTUBE, new YouTubeChatSource(
					exec, router, okHttpClient, gson,
					config.youtubeApiKey().trim(), target,
					config.youtubePollSeconds(), config.youtubeOfflineRecheckMinutes()));
			}
		}

		if (config.kickEnabled())
		{
			final List<String> channels = channelList(config.kickChannels());
			final Map<Long, String> overrides = parseChatroomIds(config.kickChatroomIds());
			if (!channels.isEmpty() || !overrides.isEmpty())
			{
				sources.put(StreamPlatform.KICK, new KickChatSource(
					exec, router, okHttpClient, gson, channels, overrides));
			}
		}

		for (ChatSource source : sources.values())
		{
			source.start();
		}

		// Clear stale state for platforms that are no longer running at all.
		for (StreamPlatform platform : StreamPlatform.values())
		{
			if (!sources.containsKey(platform) && isConfiguredOff(platform))
			{
				router.onStatus(platform, SourceStatus.DISABLED, "off");
			}
		}
	}

	private boolean isConfiguredOff(StreamPlatform platform)
	{
		switch (platform)
		{
			case TWITCH:
				return !config.twitchEnabled();
			case YOUTUBE:
				return !config.youtubeEnabled();
			case KICK:
				return !config.kickEnabled();
			default:
				return true;
		}
	}

	private void printStatus()
	{
		for (StreamPlatform platform : StreamPlatform.values())
		{
			final SourceStatus status = router.statusOf(platform);
			final String detail = router.statusDetailOf(platform);

			final Color color;
			switch (status)
			{
				case CONNECTED:
					color = Color.GREEN;
					break;
				case CONNECTING:
					color = Color.YELLOW;
					break;
				case FAILED:
					color = Color.RED;
					break;
				default:
					color = Color.GRAY;
					break;
			}

			final ChatMessageBuilder builder = new ChatMessageBuilder()
				.append(platform.getDefaultAuthorColor(), platform.getDisplayName())
				.append(": ")
				.append(color, status.name().toLowerCase(Locale.ROOT));

			if (!detail.isEmpty())
			{
				builder.append(Color.GRAY, " (" + Text.escapeJagex(detail) + ")");
			}

			client.addChatMessage(config.chatTarget().getMessageType(), "", builder.build(), null);
		}
	}

	/** Splits a comma separated channel list, normalising names to lower case. */
	static List<String> channelList(String csv)
	{
		if (csv == null)
		{
			return Collections.emptyList();
		}

		final List<String> out = new ArrayList<>();
		for (String part : Text.fromCSV(csv))
		{
			String name = part.trim().toLowerCase(Locale.ROOT);
			if (name.isEmpty())
			{
				continue;
			}

			// Tolerate a pasted URL or a leading # / @.
			final int slash = name.lastIndexOf('/');
			if (slash != -1)
			{
				name = name.substring(slash + 1);
			}
			while (!name.isEmpty() && (name.charAt(0) == '#' || name.charAt(0) == '@'))
			{
				name = name.substring(1);
			}

			if (!name.isEmpty() && !out.contains(name))
			{
				out.add(name);
			}
		}

		return out;
	}

	/** Parses the {@code slug:id, slug:id} Kick chatroom override list into {id: slug}. */
	static Map<Long, String> parseChatroomIds(String csv)
	{
		if (csv == null)
		{
			return Collections.emptyMap();
		}

		final Map<Long, String> out = new LinkedHashMap<>();
		for (String part : Text.fromCSV(csv))
		{
			final String entry = part.trim();
			final int colon = entry.lastIndexOf(':');
			if (colon <= 0 || colon == entry.length() - 1)
			{
				continue;
			}

			final String slug = entry.substring(0, colon).trim().toLowerCase(Locale.ROOT);
			try
			{
				out.put(Long.parseLong(entry.substring(colon + 1).trim()), slug);
			}
			catch (NumberFormatException ex)
			{
				log.debug("ignoring malformed Kick chatroom override: {}", entry);
			}
		}

		return out;
	}
}

