/**
 * Reads Kick chat over Kick's public Pusher chatroom socket.
 *
 * <p><b>Why not the official Kick API?</b> Kick's official developer API authenticates with
 * OAuth 2.1 + PKCE, but it delivers chat as <em>webhooks</em> -- it POSTs events to a public HTTPS
 * endpoint you host. A desktop game client has no such endpoint, and standing up a relay server
 * just to forward chat would mean routing a user's messages through third-party infrastructure.
 * Kick's own web player reads chat from the Pusher socket used here, unauthenticated, so that is
 * what this source uses.
 *
 * <p>The trade-off is that this is an undocumented endpoint and Kick may change it. Failures are
 * reported plainly in the status readout rather than being retried silently forever.
 */
@Slf4j
public class KickChatSource extends AbstractChatSource
{
	/**
	 * Kick's public Pusher application key, as used by the kick.com web player. This is a public
	 * client identifier, not a secret -- it is served to every visitor in the site's JavaScript.
	 */
	private static final String PUSHER_APP_KEY = "32cbd69e4b950bf97679";
	private static final String PUSHER_URL = "wss://ws-us2.pusher.com/app/" + PUSHER_APP_KEY
		+ "?protocol=7&client=runelite-stream-chat&version=8.4.0&flash=false";

	private static final String CHANNEL_API = "https://kick.com/api/v2/channels/";
	private static final String CHAT_MESSAGE_EVENT = "App\\Events\\ChatMessageEvent";
	private static final String SUBSCRIPTION_EVENT = "App\\Events\\SubscriptionEvent";
	private static final String GIFTED_SUBS_EVENT = "App\\Events\\GiftedSubscriptionsEvent";
	private static final String STREAM_HOST_EVENT = "App\\Events\\StreamHostEvent";

	/**
	 * Kick inlines emotes in the message body as {@code [emote:<id>:<name>]}. The game cannot show
	 * the image, so the markup is reduced to the emote's name -- which is what Twitch sends in the
	 * first place, so both platforms end up reading the same.
	 */
	private static final Pattern EMOTE_MARKUP = Pattern.compile("\\[emote:\\d+:([^\\]]*)\\]");

	private static final long INACTIVITY_TIMEOUT_MS = TimeUnit.MINUTES.toMillis(5);
	private static final long WATCHDOG_PERIOD_MS = TimeUnit.MINUTES.toMillis(1);

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final List<String> channels;
	private final Map<Long, String> chatroomOverrides;

	/** chatroom id to channel slug, resolved once per connection. */
	private final Map<Long, String> chatrooms = new LinkedHashMap<>();

	private volatile WebSocket webSocket;
	private volatile ScheduledFuture<?> watchdog;
	private volatile long lastActivityMs;

	public KickChatSource(ScheduledExecutorService executor, ChatSink sink, OkHttpClient httpClient,
		Gson gson, List<String> channels, Map<Long, String> chatroomOverrides)
	{
		super(executor, sink);
		this.httpClient = httpClient.newBuilder()
			.readTimeout(0, TimeUnit.MILLISECONDS)
			.pingInterval(30, TimeUnit.SECONDS)
			.build();
		this.gson = gson;
		this.channels = channels;
		this.chatroomOverrides = chatroomOverrides;
	}

	@Override
	public StreamPlatform platform()
	{
		return StreamPlatform.KICK;
	}

	@Override
	protected void doConnect() throws IOException
	{
		if (channels.isEmpty() && chatroomOverrides.isEmpty())
		{
			onFatal("no channels configured");
			return;
		}

		chatrooms.clear();
		chatrooms.putAll(chatroomOverrides);

		final List<String> unresolved = new ArrayList<>();
		for (String slug : channels)
		{
			if (chatrooms.containsValue(slug))
			{
				// Already supplied explicitly as a chatroom id override.
				continue;
			}

			final Long chatroomId = resolveChatroomId(slug);
			if (chatroomId == null)
			{
				unresolved.add(slug);
			}
			else
			{
				chatrooms.put(chatroomId, slug);
			}
		}

		if (chatrooms.isEmpty())
		{
			// Kick fronts its site API with Cloudflare, which intermittently refuses non-browser
			// clients. The chatroom id never changes for a channel, so the config offers a manual
			// override; point the user at it rather than retrying a block forever.
			onFatal("could not resolve chatroom id for " + String.join(", ", unresolved)
				+ " (set it manually in the Kick chatroom IDs config option)");
			return;
		}

		if (!unresolved.isEmpty())
		{
			log.warn("[Kick] could not resolve {}, continuing with {}", unresolved, chatrooms.values());
		}

		lastActivityMs = System.currentTimeMillis();
		webSocket = httpClient.newWebSocket(new Request.Builder().url(PUSHER_URL).build(), new Listener());

		watchdog = executor.scheduleWithFixedDelay(this::checkAlive,
			WATCHDOG_PERIOD_MS, WATCHDOG_PERIOD_MS, TimeUnit.MILLISECONDS);
	}

	@Override
	protected void doStop()
	{
		final ScheduledFuture<?> w = watchdog;
		if (w != null)
		{
			w.cancel(false);
			watchdog = null;
		}

		final WebSocket ws = webSocket;
		if (ws != null)
		{
			webSocket = null;
			ws.close(1000, "plugin stopped");
			ws.cancel();
		}
	}

	private void checkAlive()
	{
		if (!isRunning())
		{
			return;
		}

		if (System.currentTimeMillis() - lastActivityMs > INACTIVITY_TIMEOUT_MS)
		{
			onDisconnected("connection went quiet");
		}
	}

	/**
	 * Looks up a channel's numeric chatroom id from its slug. Returns null when the lookup is
	 * blocked or the channel does not exist.
	 */
	@Nullable
	private Long resolveChatroomId(String slug) throws IOException
	{
		final HttpUrl url = HttpUrl.get(CHANNEL_API + slug);
		final Request request = new Request.Builder()
			.url(url)
			.header("Accept", "application/json")
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful())
			{
				log.debug("[Kick] channel lookup for {} returned {}", slug, response.code());
				return null;
			}

			final ResponseBody body = response.body();
			if (body == null)
			{
				return null;
			}

			final JsonObject json = gson.fromJson(body.charStream(), JsonObject.class);
			if (json == null || !json.has("chatroom") || json.get("chatroom").isJsonNull())
			{
				return null;
			}

			final JsonObject chatroom = json.getAsJsonObject("chatroom");
			if (!chatroom.has("id") || chatroom.get("id").isJsonNull())
			{
				return null;
			}

			return chatroom.get("id").getAsLong();
		}
		catch (JsonSyntaxException | IllegalStateException | UnsupportedOperationException ex)
		{
			// A Cloudflare interstitial is HTML, not the JSON we asked for.
			log.debug("[Kick] channel lookup for {} did not return usable JSON", slug, ex);
			return null;
		}
	}

	private void handleFrame(WebSocket ws, String text)
	{
		final JsonObject frame;
		try
		{
			frame = gson.fromJson(text, JsonObject.class);
		}
		catch (JsonSyntaxException ex)
		{
			log.debug("[Kick] unparseable frame", ex);
			return;
		}

		if (frame == null || !frame.has("event") || frame.get("event").isJsonNull())
		{
			return;
		}

		final String event = frame.get("event").getAsString();
		switch (event)
		{
			case "pusher:connection_established":
				for (Long chatroomId : chatrooms.keySet())
				{
					subscribe(ws, chatroomId);
				}
				onConnected();
				break;

			case "pusher:ping":
				ws.send("{\"event\":\"pusher:pong\",\"data\":{}}");
				break;

			case "pusher:error":
				log.warn("[Kick] pusher error: {}", frame);
				onDisconnected("pusher error");
				break;

			case CHAT_MESSAGE_EVENT:
				handleChatMessage(frame);
				break;

			case SUBSCRIPTION_EVENT:
			case GIFTED_SUBS_EVENT:
			case STREAM_HOST_EVENT:
				handleEvent(event, frame);
				break;

			default:
				// pusher_internal:subscription_succeeded and Kick's other channel events.
				break;
		}
	}

	private void subscribe(WebSocket ws, long chatroomId)
	{
		// Public chatrooms need no auth token, so "auth" is deliberately empty.
		final JsonObject data = new JsonObject();
		data.addProperty("auth", "");
		data.addProperty("channel", "chatrooms." + chatroomId + ".v2");

		final JsonObject subscribe = new JsonObject();
		subscribe.addProperty("event", "pusher:subscribe");
		subscribe.add("data", data);

		ws.send(gson.toJson(subscribe));
	}

	private void handleChatMessage(JsonObject frame)
	{
		// Pusher nests the payload as a JSON *string* inside the frame.
		if (!frame.has("data") || !frame.get("data").isJsonPrimitive())
		{
			return;
		}

		final JsonObject payload;
		try
		{
			payload = gson.fromJson(frame.get("data").getAsString(), JsonObject.class);
		}
		catch (JsonSyntaxException ex)
		{
			log.debug("[Kick] unparseable chat payload", ex);
			return;
		}

		if (payload == null)
		{
			return;
		}

		final String rawContent = optString(payload, "content");
		if (rawContent == null || rawContent.isEmpty())
		{
			return;
		}

		final String content = stripEmoteMarkup(rawContent);
		if (content.isEmpty())
		{
			return;
		}

		final JsonObject sender = payload.has("sender") && payload.get("sender").isJsonObject()
			? payload.getAsJsonObject("sender")
			: null;
		if (sender == null)
		{
			return;
		}

		final String author = optString(sender, "username");
		if (author == null)
		{
			return;
		}

		Color color = null;
		if (sender.has("identity") && sender.get("identity").isJsonObject())
		{
			color = parseColor(optString(sender.getAsJsonObject("identity"), "color"));
		}

		String channel = "";
		if (payload.has("chatroom_id") && payload.get("chatroom_id").isJsonPrimitive())
		{
			channel = chatrooms.getOrDefault(payload.get("chatroom_id").getAsLong(), "");
		}

		final String id = optString(payload, "id");

		sink.onMessage(StreamChatMessage.builder()
			.platform(StreamPlatform.KICK)
			.channel(channel)
			.author(author)
			.message(content)
			.authorColor(color)
			.id(id != null ? id : author + ' ' + content)
			.emoteOnly(isEmoteOnly(rawContent))
			.build());
	}

	/**
	 * True when the message is nothing but emote markup.
	 *
	 * <p>Kick is the easy case: emotes are explicit {@code [emote:id:NAME]} tokens, so removing
	 * them outright and checking for leftovers is exact.
	 */
	static boolean isEmoteOnly(String rawContent)
	{
		if (rawContent == null || rawContent.indexOf("[emote:") == -1)
		{
			return false;
		}

		return EMOTE_MARKUP.matcher(rawContent).replaceAll("").trim().isEmpty();
	}

	/** Rewrites {@code [emote:123:KEKW]} to {@code KEKW}. */
	static String stripEmoteMarkup(String content)
	{
		if (content.indexOf("[emote:") == -1)
		{
			return content;
		}

		final Matcher m = EMOTE_MARKUP.matcher(content);
		final StringBuffer out = new StringBuffer(content.length());
		while (m.find())
		{
			// The name is user-visible text, so quote it out of the replacement syntax.
			m.appendReplacement(out, Matcher.quoteReplacement(m.group(1)));
		}
		m.appendTail(out);

		return out.toString().trim();
	}

	/**
	 * Turns Kick's subscription/host events into a readable line.
	 *
	 * <p>Kick does not send a pre-rendered message the way Twitch's {@code system-msg} does, so the
	 * wording is built here from whichever fields are present.
	 */
	private void handleEvent(String event, JsonObject frame)
	{
		if (!frame.has("data") || !frame.get("data").isJsonPrimitive())
		{
			return;
		}

		final JsonObject payload;
		try
		{
			payload = gson.fromJson(frame.get("data").getAsString(), JsonObject.class);
		}
		catch (JsonSyntaxException ex)
		{
			log.debug("[Kick] unparseable event payload", ex);
			return;
		}

		if (payload == null)
		{
			return;
		}

		final String text;
		final StreamEventType type;

		switch (event)
		{
			case SUBSCRIPTION_EVENT:
			{
				final String user = optString(payload, "username");
				if (user == null)
				{
					return;
				}
				final String months = optString(payload, "months");
				type = StreamEventType.SUBSCRIPTION;
				text = months == null
					? user + " subscribed!"
					: user + " subscribed for " + months + " months!";
				break;
			}

			case GIFTED_SUBS_EVENT:
			{
				final String gifter = optString(payload, "gifter_username");
				int count = 0;
				if (payload.has("gifted_usernames") && payload.get("gifted_usernames").isJsonArray())
				{
					count = payload.getAsJsonArray("gifted_usernames").size();
				}
				type = StreamEventType.GIFT;
				text = (gifter == null ? "Someone" : gifter) + " gifted " + count + " subs!";
				break;
			}

			case STREAM_HOST_EVENT:
			{
				final String host = optString(payload, "host_username");
				final String viewers = optString(payload, "number_viewers");
				type = StreamEventType.RAID;
				text = (host == null ? "Someone" : host) + " hosted the stream"
					+ (viewers == null ? "!" : " with " + viewers + " viewers!");
				break;
			}

			default:
				return;
		}

		sink.onMessage(StreamChatMessage.builder()
			.platform(StreamPlatform.KICK)
			.channel("")
			.author("")
			.message(text)
			.authorColor(null)
			.id(event + ' ' + text)
			.eventType(type)
			.build());
	}

	@Nullable
	private static String optString(JsonObject obj, String key)
	{
		if (!obj.has(key) || obj.get(key).isJsonNull() || !obj.get(key).isJsonPrimitive())
		{
			return null;
		}
		return obj.get(key).getAsString();
	}

	@Nullable
	static Color parseColor(@Nullable String raw)
	{
		if (raw == null || raw.length() != 7 || raw.charAt(0) != '#')
		{
			return null;
		}

		try
		{
			return new Color(Integer.parseInt(raw.substring(1), 16));
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}

	private class Listener extends WebSocketListener
	{
		@Override
		public void onMessage(WebSocket ws, String text)
		{
			lastActivityMs = System.currentTimeMillis();

			try
			{
				handleFrame(ws, text);
			}
			catch (Exception ex)
			{
				log.debug("[Kick] failed to handle frame", ex);
			}
		}

		@Override
		public void onClosed(WebSocket ws, int code, String reason)
		{
			if (webSocket == ws)
			{
				onDisconnected("closed by server (" + code + ")");
			}
		}

		@Override
		public void onFailure(WebSocket ws, Throwable t, @Nullable Response response)
		{
			if (webSocket != ws)
			{
				return;
			}

			log.debug("[Kick] websocket failure", t);
			onDisconnected(t.getMessage() == null ? t.getClass().getSimpleName() : t.getMessage());
		}
	}
}

package com.streamchat.twitch;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;

/**
 * A parsed IRCv3 line, as sent by the Twitch chat gateway.
 *
 * <p>Wire format is {@code [@tags] [:prefix] COMMAND [params...] [:trailing]}. Only the subset
 * Twitch actually emits is handled, but tag unescaping follows the IRCv3 message-tags spec in full
 * because display names and message bodies travel through tags on some events.
 */
public final class IrcMessage
{
	private final Map<String, String> tags;
	private final String prefix;
	private final String command;
	private final List<String> params;

	private IrcMessage(Map<String, String> tags, String prefix, String command, List<String> params)
	{
		this.tags = tags;
		this.prefix = prefix;
		this.command = command;
		this.params = params;
	}

	/**
	 * Parses one line. Returns null for blank lines or lines with no command, which the gateway
	 * does occasionally send.
	 */
	@Nullable
	public static IrcMessage parse(String line)
	{
		if (line == null)
		{
			return null;
		}

		// Trailing CR from the CRLF framing.
		int end = line.length();
		while (end > 0 && (line.charAt(end - 1) == '\r' || line.charAt(end - 1) == '\n'))
		{
			--end;
		}

		int pos = 0;
		while (pos < end && line.charAt(pos) == ' ')
		{
			++pos;
		}

		if (pos >= end)
		{
			return null;
		}

		Map<String, String> tags = Collections.emptyMap();
		if (line.charAt(pos) == '@')
		{
			final int sp = indexOf(line, ' ', pos, end);
			final int tagsEnd = sp == -1 ? end : sp;
			tags = parseTags(line.substring(pos + 1, tagsEnd));
			pos = sp == -1 ? end : sp + 1;
			pos = skipSpaces(line, pos, end);
		}

		String prefix = null;
		if (pos < end && line.charAt(pos) == ':')
		{
			final int sp = indexOf(line, ' ', pos, end);
			final int prefixEnd = sp == -1 ? end : sp;
			prefix = line.substring(pos + 1, prefixEnd);
			pos = sp == -1 ? end : sp + 1;
			pos = skipSpaces(line, pos, end);
		}

		if (pos >= end)
		{
			return null;
		}

		final int cmdSp = indexOf(line, ' ', pos, end);
		final int cmdEnd = cmdSp == -1 ? end : cmdSp;
		final String command = line.substring(pos, cmdEnd);
		pos = cmdSp == -1 ? end : cmdSp + 1;

		final List<String> params = new ArrayList<>(4);
		while (pos < end)
		{
			pos = skipSpaces(line, pos, end);
			if (pos >= end)
			{
				break;
			}

			if (line.charAt(pos) == ':')
			{
				// Trailing parameter: everything left, spaces included.
				params.add(line.substring(pos + 1, end));
				break;
			}

			final int sp = indexOf(line, ' ', pos, end);
			final int paramEnd = sp == -1 ? end : sp;
			params.add(line.substring(pos, paramEnd));
			pos = sp == -1 ? end : sp + 1;
		}

		return new IrcMessage(tags, prefix, command, params);
	}

	private static Map<String, String> parseTags(String raw)
	{
		if (raw.isEmpty())
		{
			return Collections.emptyMap();
		}

		final Map<String, String> out = new LinkedHashMap<>();
		int pos = 0;
		final int len = raw.length();

		while (pos <= len)
		{
			int semi = raw.indexOf(';', pos);
			if (semi == -1)
			{
				semi = len;
			}

			final String pair = raw.substring(pos, semi);
			if (!pair.isEmpty())
			{
				final int eq = pair.indexOf('=');
				if (eq == -1)
				{
					out.put(pair, "");
				}
				else
				{
					out.put(pair.substring(0, eq), unescapeTagValue(pair.substring(eq + 1)));
				}
			}

			pos = semi + 1;
			if (semi == len)
			{
				break;
			}
		}

		return out;
	}

	/** IRCv3 message-tags escaping: {@code \: ; \s space \\ backslash \r CR \n LF}. */
	static String unescapeTagValue(String value)
	{
		if (value.indexOf('\\') == -1)
		{
			return value;
		}

		final StringBuilder out = new StringBuilder(value.length());
		for (int i = 0; i < value.length(); i++)
		{
			final char c = value.charAt(i);
			if (c != '\\')
			{
				out.append(c);
				continue;
			}

			if (i + 1 >= value.length())
			{
				// A lone trailing backslash is dropped, per spec.
				break;
			}

			final char next = value.charAt(++i);
			switch (next)
			{
				case ':':
					out.append(';');
					break;
				case 's':
					out.append(' ');
					break;
				case '\\':
					out.append('\\');
					break;
				case 'r':
					out.append('\r');
					break;
				case 'n':
					out.append('\n');
					break;
				default:
					// Unrecognised escape: the escaping backslash is dropped.
					out.append(next);
					break;
			}
		}

		return out.toString();
	}

	private static int skipSpaces(String s, int pos, int end)
	{
		while (pos < end && s.charAt(pos) == ' ')
		{
			++pos;
		}
		return pos;
	}

	private static int indexOf(String s, char c, int from, int end)
	{
		for (int i = from; i < end; i++)
		{
			if (s.charAt(i) == c)
			{
				return i;
			}
		}
		return -1;
	}

	public String getCommand()
	{
		return command;
	}

	public Map<String, String> getTags()
	{
		return tags;
	}

	/** Tag value, or null when absent or empty. Twitch sends empty tags rather than omitting them. */
	@Nullable
	public String tag(String key)
	{
		final String v = tags.get(key);
		return v == null || v.isEmpty() ? null : v;
	}

	@Nullable
	public String getPrefix()
	{
		return prefix;
	}

	/** Nickname from the prefix, i.e. the part before {@code !}. */
	@Nullable
	public String nick()
	{
		if (prefix == null)
		{
			return null;
		}

		final int bang = prefix.indexOf('!');
		return bang == -1 ? prefix : prefix.substring(0, bang);
	}

	public List<String> getParams()
	{
		return params;
	}

	@Nullable
	public String param(int index)
	{
		return index >= 0 && index < params.size() ? params.get(index) : null;
	}

	/** Last parameter, which for PRIVMSG is the message body. */
	@Nullable
	public String trailing()
	{
		return params.isEmpty() ? null : params.get(params.size() - 1);
	}
}

package com.streamchat.twitch;

import com.streamchat.AbstractChatSource;
import com.streamchat.ChatSink;
import com.streamchat.StreamChatMessage;
import com.streamchat.StreamEventType;
import com.streamchat.StreamPlatform;
import java.awt.Color;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;

/**
 * Reads Twitch chat over the IRC WebSocket gateway.
 *
 * <p>Read-only access needs no OAuth at all: Twitch accepts an anonymous {@code justinfan} nick and
 * still delivers IRCv3 tags, so display names and name colours come through. That is why this
 * plugin asks for no Twitch credentials -- a token would add nothing to a read-only feed, and not
 * having one means no token to store, refresh or leak.
 */
@Slf4j
public class TwitchChatSource extends AbstractChatSource
{
	private static final String GATEWAY = "wss://irc-ws.chat.twitch.tv:443";

	/** Twitch pings roughly every five minutes; treat a longer silence as a dead socket. */
	private static final long INACTIVITY_TIMEOUT_MS = TimeUnit.MINUTES.toMillis(7);
	private static final long WATCHDOG_PERIOD_MS = TimeUnit.MINUTES.toMillis(1);

	/** CTCP delimiter (0x01). "/me" messages arrive as ACTION text wrapped in it. */
	private static final char CTCP = (char) 1;
	private static final String ACTION_PREFIX = CTCP + "ACTION ";

	private final OkHttpClient httpClient;
	private final List<String> channels;

	private volatile WebSocket webSocket;
	private volatile ScheduledFuture<?> watchdog;
	private volatile long lastActivityMs;

	public TwitchChatSource(ScheduledExecutorService executor, ChatSink sink, OkHttpClient httpClient,
		List<String> channels)
	{
		super(executor, sink);
		// A WebSocket must not inherit the shared client's read timeout, or the connection is torn
		// down during any quiet period. newBuilder() keeps the connection pool and RuneLite's
		// thread-guard interceptor.
		this.httpClient = httpClient.newBuilder()
			.readTimeout(0, TimeUnit.MILLISECONDS)
			.pingInterval(30, TimeUnit.SECONDS)
			.build();
		this.channels = channels;
	}

	@Override
	public StreamPlatform platform()
	{
		return StreamPlatform.TWITCH;
	}

	@Override
	protected void doConnect()
	{
		if (channels.isEmpty())
		{
			onFatal("no channels configured");
			return;
		}

		final Request request = new Request.Builder()
			.url(GATEWAY)
			.build();

		lastActivityMs = System.currentTimeMillis();
		webSocket = httpClient.newWebSocket(request, new Listener());

		watchdog = executor.scheduleWithFixedDelay(this::checkAlive,
			WATCHDOG_PERIOD_MS, WATCHDOG_PERIOD_MS, TimeUnit.MILLISECONDS);
	}

	@Override
	protected void doStop()
	{
		final ScheduledFuture<?> w = watchdog;
		if (w != null)
		{
			w.cancel(false);
			watchdog = null;
		}

		final WebSocket ws = webSocket;
		if (ws != null)
		{
			webSocket = null;
			// 1000 = normal closure. cancel() too, so a half-open socket cannot linger.
			ws.close(1000, "plugin stopped");
			ws.cancel();
		}
	}

	private void checkAlive()
	{
		if (!isRunning())
		{
			return;
		}

		if (System.currentTimeMillis() - lastActivityMs > INACTIVITY_TIMEOUT_MS)
		{
			log.debug("[Twitch] no traffic for {}ms, reconnecting", INACTIVITY_TIMEOUT_MS);
			onDisconnected("connection went quiet");
		}
	}

	private void send(WebSocket ws, String line)
	{
		ws.send(line + "\r\n");
	}

	private void handleLine(WebSocket ws, String line)
	{
		final IrcMessage msg = IrcMessage.parse(line);
		if (msg == null)
		{
			return;
		}

		switch (msg.getCommand())
		{
			case "PING":
				// Must echo the token back or Twitch drops the connection.
				send(ws, "PONG :" + (msg.trailing() == null ? "tmi.twitch.tv" : msg.trailing()));
				break;

			case "001":
				// Registered. Join here, so a reconnect re-joins with no extra bookkeeping.
				for (String channel : channels)
				{
					send(ws, "JOIN #" + channel.toLowerCase(Locale.ROOT));
				}
				onConnected();
				break;

			case "PRIVMSG":
				handlePrivmsg(msg);
				break;

			case "USERNOTICE":
				handleUserNotice(msg);
				break;

			case "NOTICE":
				handleNotice(msg);
				break;

			case "RECONNECT":
				// Twitch asks clients to reconnect before it restarts a gateway node.
				onDisconnected("server requested reconnect");
				break;

			default:
				break;
		}
	}

	private void handlePrivmsg(IrcMessage msg)
	{
		final String channel = stripHash(msg.param(0));
		String body = msg.trailing();
		if (body == null || body.isEmpty())
		{
			return;
		}

		if (body.startsWith(ACTION_PREFIX))
		{
			final int bodyEnd = body.charAt(body.length() - 1) == CTCP ? body.length() - 1 : body.length();
			body = "* " + body.substring(Math.min(ACTION_PREFIX.length(), bodyEnd), bodyEnd);
		}

		String author = msg.tag("display-name");
		if (author == null)
		{
			author = msg.nick();
		}
		if (author == null)
		{
			return;
		}

		final String id = msg.tag("id");
		// A cheer is an ordinary message that also carries bits.
		final StreamEventType eventType = msg.tag("bits") != null ? StreamEventType.CHEER : null;

		sink.onMessage(StreamChatMessage.builder()
			.platform(StreamPlatform.TWITCH)
			.channel(channel)
			.author(author)
			.message(body)
			.authorColor(parseColor(msg.tag("color")))
			.id(id != null ? id : syntheticId(author, body))
			.eventType(eventType)
			.emoteOnly(isEmoteOnly(msg.trailing(), msg.tag("emotes")))
			.build());
	}

	private void handleUserNotice(IrcMessage msg)
	{
		// system-msg carries the pre-rendered "X subscribed for n months" text.
		final String system = msg.tag("system-msg");
		if (system == null)
		{
			return;
		}

		final String id = msg.tag("id");

		sink.onMessage(StreamChatMessage.builder()
			.platform(StreamPlatform.TWITCH)
			.channel(stripHash(msg.param(0)))
			.author("")
			.message(system)
			.authorColor(null)
			.id(id != null ? id : syntheticId("", system))
			.eventType(classifyUserNotice(msg.tag("msg-id")))
			.build());
	}

	/**
	 * Works out whether a message is nothing but emotes, from the IRCv3 {@code emotes} tag.
	 *
	 * <p>The tag gives character ranges, e.g. {@code 25:0-4,12-16/1902:6-10}. If every non-space
	 * character falls inside one of those ranges, the user typed no words of their own.
	 *
	 * <p>Only native Twitch emotes appear in this tag. BTTV/FFZ/7TV emotes are plain words as far
	 * as the protocol is concerned, and identifying them would mean downloading those services'
	 * emote lists -- which is exactly what the Plugin Hub rejects emote plugins for. So third-party
	 * emotes are treated as ordinary text, which errs towards showing a message rather than hiding
	 * one.
	 */
	static boolean isEmoteOnly(@Nullable String message, @Nullable String emotesTag)
	{
		if (message == null || message.isEmpty() || emotesTag == null || emotesTag.isEmpty())
		{
			return false;
		}

		final boolean[] covered = new boolean[message.length()];

		for (String emote : emotesTag.split("/"))
		{
			final int colon = emote.indexOf(':');
			if (colon == -1)
			{
				continue;
			}

			for (String range : emote.substring(colon + 1).split(","))
			{
				final int dash = range.indexOf('-');
				if (dash == -1)
				{
					continue;
				}

				try
				{
					final int start = Integer.parseInt(range.substring(0, dash).trim());
					final int end = Integer.parseInt(range.substring(dash + 1).trim());
					for (int i = Math.max(0, start); i <= Math.min(covered.length - 1, end); i++)
					{
						covered[i] = true;
					}
				}
				catch (NumberFormatException ex)
				{
					return false;
				}
			}
		}

		boolean sawEmote = false;
		for (int i = 0; i < message.length(); i++)
		{
			if (covered[i])
			{
				sawEmote = true;
			}
			else if (!Character.isWhitespace(message.charAt(i)))
			{
				return false;
			}
		}

		return sawEmote;
	}

	/** Maps Twitch's USERNOTICE msg-id to an event kind. */
	static StreamEventType classifyUserNotice(@Nullable String msgId)
	{
		if (msgId == null)
		{
			return StreamEventType.OTHER;
		}

		switch (msgId)
		{
			case "sub":
			case "resub":
			case "extendsub":
			case "primepaidupgrade":
			case "giftpaidupgrade":
			case "anongiftpaidupgrade":
				return StreamEventType.SUBSCRIPTION;

			case "subgift":
			case "anonsubgift":
			case "submysterygift":
			case "standardpayforward":
			case "communitypayforward":
				return StreamEventType.GIFT;

			case "raid":
			case "unraid":
				return StreamEventType.RAID;

			case "bitsbadgetier":
				return StreamEventType.CHEER;

			default:
				return StreamEventType.OTHER;
		}
	}

	private void handleNotice(IrcMessage msg)
	{
		final String msgId = msg.tag("msg-id");
		if (msgId == null)
		{
			return;
		}

		// These mean the channel will never deliver messages, so retrying is pointless.
		switch (msgId)
		{
			case "msg_channel_suspended":
			case "msg_banned":
			case "no_permission":
			case "tos_ban":
				onFatal(msg.trailing() == null ? msgId : msg.trailing());
				break;
			default:
				log.debug("[Twitch] notice {}: {}", msgId, msg.trailing());
				break;
		}
	}

	private static String stripHash(@Nullable String channel)
	{
		if (channel == null)
		{
			return "";
		}
		return channel.startsWith("#") ? channel.substring(1) : channel;
	}

	/**
	 * Twitch name colours are {@code #RRGGBB}. Returns null for the empty tag Twitch sends for
	 * users who never picked one.
	 */
	@Nullable
	static Color parseColor(@Nullable String raw)
	{
		if (raw == null || raw.length() != 7 || raw.charAt(0) != '#')
		{
			return null;
		}

		try
		{
			return new Color(Integer.parseInt(raw.substring(1), 16));
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}

	private static String syntheticId(String author, String body)
	{
		return author + ' ' + body;
	}

	private class Listener extends WebSocketListener
	{
		@Override
		public void onOpen(WebSocket ws, Response response)
		{
			lastActivityMs = System.currentTimeMillis();

			// tags gives us display names and colours; commands gives us RECONNECT and NOTICE.
			send(ws, "CAP REQ :twitch.tv/tags twitch.tv/commands");
			// Anonymous read-only login. Any justinfan<digits> nick is accepted with no password.
			send(ws, "NICK justinfan" + (ThreadLocalRandom.current().nextInt(90_000) + 10_000));
		}

		@Override
		public void onMessage(WebSocket ws, String text)
		{
			lastActivityMs = System.currentTimeMillis();

			// A single frame can carry several CRLF-separated lines.
			int start = 0;
			while (start < text.length())
			{
				int nl = text.indexOf('\n', start);
				if (nl == -1)
				{
					nl = text.length();
				}

				final String line = text.substring(start, nl);
				if (!line.trim().isEmpty())
				{
					try
					{
						handleLine(ws, line);
					}
					catch (Exception ex)
					{
						log.debug("[Twitch] failed to handle line: {}", line, ex);
					}
				}

				start = nl + 1;
			}
		}

		@Override
		public void onClosed(WebSocket ws, int code, String reason)
		{
			if (webSocket == ws)
			{
				onDisconnected("closed by server (" + code + ")");
			}
		}

		@Override
		public void onFailure(WebSocket ws, Throwable t, @Nullable Response response)
		{
			if (webSocket != ws)
			{
				// A socket we already replaced or cancelled.
				return;
			}

			log.debug("[Twitch] websocket failure", t);
			onDisconnected(t.getMessage() == null ? t.getClass().getSimpleName() : t.getMessage());
		}
	}
}

package com.streamchat.youtube;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonSyntaxException;
import com.streamchat.AbstractChatSource;
import com.streamchat.ChatSink;
import com.streamchat.StreamChatMessage;
import com.streamchat.StreamEventType;
import com.streamchat.StreamPlatform;
import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.regex.Pattern;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Reads YouTube live chat through the YouTube Data API v3.
 *
 * <p><b>Auth.</b> Reading a public live chat is public read-only data, which Google authenticates
 * with an API key rather than OAuth. The plugin therefore asks for a key the user creates in their
 * own Google Cloud project: the quota consumed is theirs, the key stays in their RuneLite config,
 * and no shared credential ships with the plugin. OAuth would only be required to read a private or
 * unlisted broadcast, or to post messages, and this plugin does neither.
 *
 * <p><b>Quota.</b> This is the one real constraint. A Google project gets 10,000 units/day.
 * {@code liveChatMessages.list} costs 5 units per poll, so polling every 5 seconds spends about
 * 3,600 units per hour -- roughly 2.5 hours of viewing per day. Resolving a target costs 1 unit for
 * a video id but 100 units for a channel id or handle, because that needs {@code search.list}.
 * Because of that gap, a channel target is re-checked on a deliberately slow timer while it is
 * offline, and the config text steers users towards pasting the live video URL.
 */
@Slf4j
public class YouTubeChatSource extends AbstractChatSource
{
	private static final HttpUrl API_BASE = HttpUrl.get("https://www.googleapis.com/youtube/v3/");

	/** Floor on the API's suggested poll interval, so a busy chat cannot drain the daily quota. */
	private static final long MIN_POLL_INTERVAL_MS = 2_000L;
	private static final long DEFAULT_POLL_INTERVAL_MS = 5_000L;

	/** One or more {@code :shortcode:} tokens and nothing else. */
	private static final Pattern EMOJI_SHORTCODES =
		Pattern.compile("(?:\\s*:[A-Za-z0-9_+-]+:\\s*)+");

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final String apiKey;
	private final YouTubeTarget target;
	private final long minPollIntervalMs;
	private final long offlineRecheckMs;

	private volatile ScheduledFuture<?> pollTask;
	private volatile String liveChatId;
	private volatile String nextPageToken;

	/**
	 * The API replays recent history on the first page. Showing it would dump a wall of stale
	 * messages into the chatbox on every connect, so the first page is consumed for its page token
	 * only.
	 */
	private volatile boolean primed;

	public YouTubeChatSource(ScheduledExecutorService executor, ChatSink sink, OkHttpClient httpClient,
		Gson gson, String apiKey, YouTubeTarget target, int minPollSeconds, int offlineRecheckMinutes)
	{
		super(executor, sink);
		this.httpClient = httpClient;
		this.gson = gson;
		this.apiKey = apiKey;
		this.target = target;
		this.minPollIntervalMs = Math.max(MIN_POLL_INTERVAL_MS, TimeUnit.SECONDS.toMillis(minPollSeconds));
		this.offlineRecheckMs = TimeUnit.MINUTES.toMillis(Math.max(1, offlineRecheckMinutes));
	}

	@Override
	public StreamPlatform platform()
	{
		return StreamPlatform.YOUTUBE;
	}

	@Override
	protected void doConnect() throws IOException
	{
		if (apiKey.isEmpty())
		{
			onFatal("no API key configured");
			return;
		}

		liveChatId = null;
		nextPageToken = null;
		primed = false;

		final String videoId = resolveVideoId();
		if (videoId == null)
		{
			scheduleOfflineRecheck();
			return;
		}

		liveChatId = resolveLiveChatId(videoId);
		if (liveChatId == null)
		{
			scheduleOfflineRecheck();
			return;
		}

		onConnected();
		schedulePoll(0L);
	}

	@Override
	protected void doStop()
	{
		final ScheduledFuture<?> p = pollTask;
		if (p != null)
		{
			p.cancel(false);
			pollTask = null;
		}
	}

	/**
	 * A stream that has not started yet is normal, not an error. Re-check on a slow fixed timer
	 * rather than the usual backoff, because for a channel target each check costs 100 quota units.
	 */
	private void scheduleOfflineRecheck()
	{
		if (!isRunning())
		{
			return;
		}

		final long delay = target.isExpensiveToResolve() ? offlineRecheckMs : Math.min(offlineRecheckMs, 60_000L);
		log.debug("[YouTube] target not live, re-checking in {}ms", delay);

		pollTask = executor.schedule(() ->
		{
			if (!isRunning())
			{
				return;
			}

			try
			{
				doConnect();
			}
			catch (Exception ex)
			{
				onDisconnected(ex.getMessage() == null ? ex.getClass().getSimpleName() : ex.getMessage());
			}
		}, delay, TimeUnit.MILLISECONDS);
	}

	@Nullable
	private String resolveVideoId() throws IOException
	{
		switch (target.getKind())
		{
			case VIDEO:
				return target.getValue();

			case CHANNEL_ID:
				return findLiveVideoForChannel(target.getValue());

			case HANDLE:
			{
				final String channelId = resolveHandleToChannelId(target.getValue());
				return channelId == null ? null : findLiveVideoForChannel(channelId);
			}

			default:
				return null;
		}
	}

	/** channels.list with forHandle: 1 quota unit. */
	@Nullable
	private String resolveHandleToChannelId(String handle) throws IOException
	{
		final HttpUrl url = API_BASE.newBuilder()
			.addPathSegment("channels")
			.addQueryParameter("part", "id")
			.addQueryParameter("forHandle", "@" + handle)
			.addQueryParameter("key", apiKey)
			.build();

		final JsonObject json = get(url);
		if (json == null)
		{
			return null;
		}

		final JsonArray items = optArray(json, "items");
		if (items == null || items.size() == 0)
		{
			onFatal("no YouTube channel found for @" + handle);
			return null;
		}

		return optString(items.get(0).getAsJsonObject(), "id");
	}

	/** search.list: 100 quota units. Only used for channel/handle targets. */
	@Nullable
	private String findLiveVideoForChannel(String channelId) throws IOException
	{
		final HttpUrl url = API_BASE.newBuilder()
			.addPathSegment("search")
			.addQueryParameter("part", "id")
			.addQueryParameter("channelId", channelId)
			.addQueryParameter("eventType", "live")
			.addQueryParameter("type", "video")
			.addQueryParameter("maxResults", "1")
			.addQueryParameter("key", apiKey)
			.build();

		final JsonObject json = get(url);
		if (json == null)
		{
			return null;
		}

		final JsonArray items = optArray(json, "items");
		if (items == null || items.size() == 0)
		{
			return null;
		}

		final JsonObject id = optObject(items.get(0).getAsJsonObject(), "id");
		return id == null ? null : optString(id, "videoId");
	}

	/** videos.list: 1 quota unit. */
	@Nullable
	private String resolveLiveChatId(String videoId) throws IOException
	{
		final HttpUrl url = API_BASE.newBuilder()
			.addPathSegment("videos")
			.addQueryParameter("part", "liveStreamingDetails")
			.addQueryParameter("id", videoId)
			.addQueryParameter("key", apiKey)
			.build();

		final JsonObject json = get(url);
		if (json == null)
		{
			return null;
		}

		final JsonArray items = optArray(json, "items");
		if (items == null || items.size() == 0)
		{
			onFatal("no YouTube video found for id " + videoId);
			return null;
		}

		final JsonObject details = optObject(items.get(0).getAsJsonObject(), "liveStreamingDetails");
		if (details == null)
		{
			// Not a livestream at all, as opposed to a stream that has not started.
			onFatal("video " + videoId + " is not a livestream");
			return null;
		}

		// Absent once the broadcast ends, or before it starts.
		return optString(details, "activeLiveChatId");
	}

	private void schedulePoll(long delayMs)
	{
		if (!isRunning())
		{
			return;
		}

		pollTask = executor.schedule(this::poll, delayMs, TimeUnit.MILLISECONDS);
	}

	private void poll()
	{
		if (!isRunning())
		{
			return;
		}

		try
		{
			final long next = pollOnce();
			schedulePoll(next);
		}
		catch (IOException ex)
		{
			log.debug("[YouTube] poll failed", ex);
			onDisconnected(ex.getMessage() == null ? ex.getClass().getSimpleName() : ex.getMessage());
		}
		catch (Exception ex)
		{
			log.warn("[YouTube] unexpected poll error", ex);
			onDisconnected("unexpected error");
		}
	}

	/** Returns the delay before the next poll, in milliseconds. */
	private long pollOnce() throws IOException
	{
		final HttpUrl.Builder url = API_BASE.newBuilder()
			.addPathSegment("liveChat")
			.addPathSegment("messages")
			.addQueryParameter("liveChatId", liveChatId)
			.addQueryParameter("part", "snippet,authorDetails")
			.addQueryParameter("maxResults", "200")
			.addQueryParameter("key", apiKey);

		if (nextPageToken != null)
		{
			url.addQueryParameter("pageToken", nextPageToken);
		}

		final JsonObject json = get(url.build());
		if (json == null)
		{
			// get() already reported the reason; back off via the normal path.
			return minPollIntervalMs;
		}

		nextPageToken = optString(json, "nextPageToken");

		final JsonArray items = optArray(json, "items");
		if (items != null && primed)
		{
			for (int i = 0; i < items.size(); i++)
			{
				if (items.get(i).isJsonObject())
				{
					emit(items.get(i).getAsJsonObject());
				}
			}
		}

		primed = true;

		long interval = DEFAULT_POLL_INTERVAL_MS;
		if (json.has("pollingIntervalMillis") && json.get("pollingIntervalMillis").isJsonPrimitive())
		{
			interval = json.get("pollingIntervalMillis").getAsLong();
		}

		return Math.max(minPollIntervalMs, interval);
	}

	private void emit(JsonObject item)
	{
		final JsonObject snippet = optObject(item, "snippet");
		final JsonObject author = optObject(item, "authorDetails");
		if (snippet == null || author == null)
		{
			return;
		}

		// textMessageEvent is a normal chat line. Superchats and membership events carry their text
		// elsewhere; displayMessage covers the common cases in one field.
		String text = optString(snippet, "displayMessage");
		if (text == null)
		{
			final JsonObject details = optObject(snippet, "textMessageDetails");
			text = details == null ? null : optString(details, "messageText");
		}

		if (text == null || text.isEmpty())
		{
			return;
		}

		final String name = optString(author, "displayName");
		if (name == null)
		{
			return;
		}

		final String id = optString(item, "id");

		sink.onMessage(StreamChatMessage.builder()
			.platform(StreamPlatform.YOUTUBE)
			.channel("")
			.author(name)
			.message(text)
			.authorColor(null)
			.id(id != null ? id : name + ' ' + text)
			.eventType(classify(optString(snippet, "type")))
			.emoteOnly(isEmoteOnly(text))
			.build());
	}

	/**
	 * True when the message is only YouTube custom emoji.
	 *
	 * <p>YouTube renders channel emoji into {@code displayMessage} as {@code :shortcode:} tokens.
	 * Unicode emoji need no handling here: {@link com.streamchat.ChatText#clean} already drops
	 * anything the game font cannot draw, and a message left empty by that is discarded anyway.
	 */
	static boolean isEmoteOnly(@Nullable String text)
	{
		if (text == null)
		{
			return false;
		}

		final String trimmed = text.trim();
		return !trimmed.isEmpty() && EMOJI_SHORTCODES.matcher(trimmed).matches();
	}

	/**
	 * Maps a live chat message type to an event kind, or null for an ordinary chat line.
	 *
	 * <p>YouTube reports memberships and Super Chats as distinct message types rather than as
	 * separate events, so they arrive on the same feed as normal chat.
	 */
	@Nullable
	static StreamEventType classify(@Nullable String snippetType)
	{
		if (snippetType == null)
		{
			return null;
		}

		switch (snippetType)
		{
			case "newSponsorEvent":
			case "memberMilestoneChatEvent":
				return StreamEventType.SUBSCRIPTION;

			case "membershipGiftingEvent":
			case "giftMembershipReceivedEvent":
				return StreamEventType.GIFT;

			case "superChatEvent":
			case "superStickerEvent":
				return StreamEventType.DONATION;

			case "textMessageEvent":
			case "chatEndedEvent":
			case "tombstone":
				return null;

			default:
				return null;
		}
	}

	/**
	 * Performs a GET and returns the parsed body, or null after reporting the failure. Google's
	 * error {@code reason} distinguishes "try again later" from "this will never work", which is
	 * what decides between a retry and giving up.
	 */
	@Nullable
	private JsonObject get(HttpUrl url) throws IOException
	{
		final Request request = new Request.Builder()
			.url(url)
			.header("Accept", "application/json")
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			final ResponseBody body = response.body();
			final String raw = body == null ? "" : body.string();

			if (response.isSuccessful())
			{
				try
				{
					return gson.fromJson(raw, JsonObject.class);
				}
				catch (JsonSyntaxException ex)
				{
					throw new IOException("malformed response from YouTube", ex);
				}
			}

			handleApiError(response.code(), raw);
			return null;
		}
	}

	private void handleApiError(int code, String raw) throws IOException
	{
		String reason = "";
		String message = "";

		try
		{
			final JsonObject json = gson.fromJson(raw, JsonObject.class);
			final JsonObject error = json == null ? null : optObject(json, "error");
			if (error != null)
			{
				message = optString(error, "message") == null ? "" : optString(error, "message");
				final JsonArray errors = optArray(error, "errors");
				if (errors != null && errors.size() > 0 && errors.get(0).isJsonObject())
				{
					final String r = optString(errors.get(0).getAsJsonObject(), "reason");
					reason = r == null ? "" : r;
				}
			}
		}
		catch (JsonSyntaxException ignored)
		{
			// Fall through to the status-code handling below.
		}

		switch (reason)
		{
			case "quotaExceeded":
			case "dailyLimitExceeded":
				onFatal("YouTube API quota exhausted for today; raise the poll interval or use a video URL");
				return;

			case "keyInvalid":
			case "badRequest":
			case "forbidden":
			case "liveChatDisabled":
				onFatal("YouTube rejected the request: " + (message.isEmpty() ? reason : message));
				return;

			case "liveChatEnded":
			case "liveChatNotFound":
				// The broadcast finished. Go back to looking for the next one.
				liveChatId = null;
				nextPageToken = null;
				primed = false;
				scheduleOfflineRecheck();
				return;

			case "rateLimitExceeded":
			case "backendError":
				throw new IOException("YouTube temporarily unavailable (" + reason + ")");

			default:
				break;
		}

		if (code == 401 || code == 403)
		{
			onFatal("YouTube rejected the API key" + (message.isEmpty() ? "" : ": " + message));
			return;
		}

		throw new IOException("YouTube returned HTTP " + code + (message.isEmpty() ? "" : ": " + message));
	}

	@Nullable
	private static String optString(JsonObject obj, String key)
	{
		if (obj == null || !obj.has(key) || obj.get(key).isJsonNull() || !obj.get(key).isJsonPrimitive())
		{
			return null;
		}
		return obj.get(key).getAsString();
	}

	@Nullable
	private static JsonObject optObject(JsonObject obj, String key)
	{
		if (obj == null || !obj.has(key) || !obj.get(key).isJsonObject())
		{
			return null;
		}
		return obj.getAsJsonObject(key);
	}

	@Nullable
	private static JsonArray optArray(JsonObject obj, String key)
	{
		if (obj == null || !obj.has(key) || !obj.get(key).isJsonArray())
		{
			return null;
		}
		return obj.getAsJsonArray(key);
	}
}

package com.streamchat.youtube;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.annotation.Nullable;
import lombok.Value;

/**
 * What the user typed into the YouTube target config option, resolved into something the Data API
 * can look up.
 *
 * <p>The distinction matters for quota: a video id costs 1 unit to resolve, whereas finding the
 * current live video for a channel costs 100 units because it needs {@code search.list}. Accepting
 * either, and telling the two apart reliably, is what lets the plugin recommend the cheap path.
 */
@Value
public class YouTubeTarget
{
	public enum Kind
	{
		VIDEO,
		CHANNEL_ID,
		HANDLE
	}

	Kind kind;
	String value;

	private static final Pattern VIDEO_ID = Pattern.compile("^[A-Za-z0-9_-]{11}$");
	private static final Pattern CHANNEL_ID = Pattern.compile("^UC[A-Za-z0-9_-]{22}$");

	// youtube.com/watch?v=ID, youtu.be/ID, youtube.com/live/ID, youtube.com/embed/ID
	private static final Pattern URL_VIDEO = Pattern.compile(
		"(?:youtube\\.com/(?:watch\\?(?:.*&)?v=|live/|embed/|shorts/)|youtu\\.be/)([A-Za-z0-9_-]{11})");
	private static final Pattern URL_CHANNEL = Pattern.compile("youtube\\.com/channel/(UC[A-Za-z0-9_-]{22})");
	private static final Pattern URL_HANDLE = Pattern.compile("youtube\\.com/@([A-Za-z0-9._-]+)");

	/**
	 * Parses a video id, channel id, {@code @handle}, or any of the common YouTube URL forms.
	 * Returns null when the input is blank or unrecognised.
	 */
	@Nullable
	public static YouTubeTarget parse(@Nullable String raw)
	{
		if (raw == null)
		{
			return null;
		}

		final String input = raw.trim();
		if (input.isEmpty())
		{
			return null;
		}

		if (input.toLowerCase(Locale.ROOT).contains("youtu"))
		{
			final Matcher video = URL_VIDEO.matcher(input);
			if (video.find())
			{
				return new YouTubeTarget(Kind.VIDEO, video.group(1));
			}

			final Matcher channel = URL_CHANNEL.matcher(input);
			if (channel.find())
			{
				return new YouTubeTarget(Kind.CHANNEL_ID, channel.group(1));
			}

			final Matcher handle = URL_HANDLE.matcher(input);
			if (handle.find())
			{
				return new YouTubeTarget(Kind.HANDLE, handle.group(1));
			}

			return null;
		}

		if (input.startsWith("@"))
		{
			final String handle = input.substring(1);
			return handle.isEmpty() ? null : new YouTubeTarget(Kind.HANDLE, handle);
		}

		// Check channel id first: "UC" + 22 chars is 24 long, so it cannot collide with a video id.
		if (CHANNEL_ID.matcher(input).matches())
		{
			return new YouTubeTarget(Kind.CHANNEL_ID, input);
		}

		if (VIDEO_ID.matcher(input).matches())
		{
			return new YouTubeTarget(Kind.VIDEO, input);
		}

		return null;
	}

	/** True when resolving this target needs {@code search.list}, which costs 100 quota units. */
	public boolean isExpensiveToResolve()
	{
		return kind != Kind.VIDEO;
	}
}

package com.streamchat;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.client.util.Text;
import org.junit.Test;

/**
 * The sanitising path is the plugin's security boundary, so these tests cover the injection cases
 * explicitly rather than only the happy path.
 */
public class ChatTextTest
{
	private static final int LEN = 180;

	@Test
	public void passesOrdinaryText()
	{
		assertEquals("hello world", ChatText.clean("hello world", LEN));
	}

	@Test
	public void collapsesWhitespaceAndNewlines()
	{
		assertEquals("a b c", ChatText.clean("a\n\nb\t\tc", LEN));
		assertEquals("a b", ChatText.clean("  a     b  ", LEN));
	}

	@Test
	public void stripsNonBreakingSpace()
	{
		// Twitch clients append U+00A0 so a user can repeat an identical message.
		assertEquals("gg", ChatText.clean("gg\u00A0", LEN));
	}

	@Test
	public void stripsUnrenderableCharacters()
	{
		// Emoji and control characters have no glyph in the game font.
		assertEquals("hi", ChatText.clean("hi\uD83D\uDE00", LEN));
		assertEquals("ab", ChatText.clean("a" + (char) 1 + "b", LEN));
		assertEquals("", ChatText.clean("\uD83D\uDE00\uD83D\uDE00", LEN));
	}

	@Test
	public void keepsLatin1Characters()
	{
		// 160-255 are renderable, so accented names survive.
		assertEquals("Jos\u00E9", ChatText.clean("Jos\u00E9", LEN));
	}

	@Test
	public void truncatesWithEllipsis()
	{
		final String out = ChatText.clean(repeat("a", 300), 50);

		assertEquals(50, out.length());
		assertTrue(out.endsWith("..."));
	}

	@Test
	public void escapingNeutralisesTagInjection()
	{
		// A chatter typing an <img> tag must not be able to fake a mod crown in the chatbox.
		final String cleaned = ChatText.clean("<img=1> nice crown", LEN);
		final String escaped = Text.escapeJagex(cleaned);

		assertFalse(escaped.contains("<img="));
		assertEquals("<lt>img=1<gt> nice crown", escaped);
	}

	@Test
	public void escapingNeutralisesColourInjection()
	{
		final String escaped = Text.escapeJagex(ChatText.clean("<col=ff0000>red", LEN));

		assertFalse(escaped.contains("<col="));
		assertEquals("<lt>col=ff0000<gt>red", escaped);
	}

	@Test
	public void truncationCannotSplitAnEscapeSequence()
	{
		// Truncating before escaping is what guarantees this: escaping a cut string can never
		// produce a half-written <lt>.
		for (int limit = 20; limit <= 40; limit++)
		{
			final String escaped = Text.escapeJagex(ChatText.clean(repeat("<", 60), limit));

			assertFalse("limit " + limit + " produced " + escaped, escaped.contains("<l>"));
			assertFalse("limit " + limit + " produced " + escaped, escaped.endsWith("<l"));
			assertFalse("limit " + limit + " produced " + escaped, escaped.endsWith("<"));
		}
	}

	@Test
	public void handlesNullAndEmpty()
	{
		assertEquals("", ChatText.clean(null, LEN));
		assertEquals("", ChatText.clean("", LEN));
		assertEquals("", ChatText.clean("     ", LEN));
	}

	private static String repeat(String s, int n)
	{
		final StringBuilder sb = new StringBuilder(s.length() * n);
		for (int i = 0; i < n; i++)
		{
			sb.append(s);
		}
		return sb.toString();
	}
}

package com.streamchat;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class EventTriggerTest
{
	@Test
	public void triggerScopes()
	{
		assertTrue(EventTrigger.ALL.matches(StreamEventType.CHEER));
		assertTrue(EventTrigger.ALL.matches(StreamEventType.SUBSCRIPTION));

		assertTrue(EventTrigger.SUBS_AND_GIFTS.matches(StreamEventType.SUBSCRIPTION));
		assertTrue(EventTrigger.SUBS_AND_GIFTS.matches(StreamEventType.GIFT));
		assertTrue(EventTrigger.SUBS_AND_GIFTS.matches(StreamEventType.RAID));
		assertFalse(EventTrigger.SUBS_AND_GIFTS.matches(StreamEventType.CHEER));

		assertTrue(EventTrigger.SUBS_ONLY.matches(StreamEventType.SUBSCRIPTION));
		assertFalse(EventTrigger.SUBS_ONLY.matches(StreamEventType.GIFT));
	}

	@Test
	public void ordinaryMessagesNeverTriggerReactions()
	{
		// A null event type is an ordinary chat line, which must never set off a sound or emote.
		for (EventTrigger trigger : EventTrigger.values())
		{
			assertFalse(trigger.toString(), trigger.matches(null));
		}
	}

	@Test
	public void messageKnowsWhetherItIsAnEvent()
	{
