			.platform(StreamPlatform.TWITCH).channel("c").author("a").message("m").id("1").build();
		final StreamChatMessage event = StreamChatMessage.builder()
			.platform(StreamPlatform.TWITCH).channel("c").author("").message("subbed").id("2")
			.eventType(StreamEventType.SUBSCRIPTION).build();

		assertFalse(chat.isEvent());
		assertTrue(event.isEvent());
	}
}

package com.streamchat;

import com.streamchat.MessageRouter.Queued;
import java.util.ArrayDeque;
import java.util.Deque;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class MessageRouterTest
{
	private static final long NOW = 1_000_000L;
	private static final long MAX_AGE = 30_000L;

	private static Queued at(long receivedAtMs)
	{
		return new Queued(StreamChatMessage.builder()
			.platform(StreamPlatform.TWITCH)
			.channel("c")
			.author("a")
			.message("m")
			.id(Long.toString(receivedAtMs))
			.build(), receivedAtMs);
	}

	@Test
	public void keepsFreshMessages()
	{
		final Deque<Queued> q = new ArrayDeque<>();
		q.add(at(NOW - 1_000));
		q.add(at(NOW - 500));

		assertEquals(0, MessageRouter.purgeStale(q, NOW, MAX_AGE));
		assertEquals(2, q.size());
	}

	@Test
	public void dropsEverythingOlderThanTheCap()
	{
		// The login-screen case: a full queue built up while no game ticks were firing.
		final Deque<Queued> q = new ArrayDeque<>();
		for (int i = 0; i < 100; i++)
		{
			q.add(at(NOW - 120_000 + i));
		}

		assertEquals(100, MessageRouter.purgeStale(q, NOW, MAX_AGE));
		assertTrue(q.isEmpty());
	}

	@Test
	public void purgeIsNotRationed()
	{
		// The whole point: stale entries go in one pass, not a couple per tick, or clearing a
		// backlog would itself take half a minute of bursty output.
		final Deque<Queued> q = new ArrayDeque<>();
		for (int i = 0; i < 500; i++)
		{
			q.add(at(NOW - 60_000));
		}

		assertEquals(500, MessageRouter.purgeStale(q, NOW, MAX_AGE));
		assertEquals(0, q.size());
	}

	@Test
	public void stopsAtTheFirstFreshMessage()
	{
		final Deque<Queued> q = new ArrayDeque<>();
		q.add(at(NOW - 90_000));
		q.add(at(NOW - 60_000));
		q.add(at(NOW - 1_000));
		q.add(at(NOW));

		assertEquals(2, MessageRouter.purgeStale(q, NOW, MAX_AGE));
		assertEquals(2, q.size());
		assertEquals(NOW - 1_000, q.peekFirst().receivedAtMs);
	}

	@Test
	public void boundaryIsExclusive()
	{
		final Deque<Queued> q = new ArrayDeque<>();
		q.add(at(NOW - MAX_AGE));

		// Exactly at the cap is still young enough.
		assertEquals(0, MessageRouter.purgeStale(q, NOW, MAX_AGE));

		q.clear();
		q.add(at(NOW - MAX_AGE - 1));
		assertEquals(1, MessageRouter.purgeStale(q, NOW, MAX_AGE));
	}

	@Test
	public void handlesEmptyQueue()
	{
		final Deque<Queued> q = new ArrayDeque<>();
		assertEquals(0, MessageRouter.purgeStale(q, NOW, MAX_AGE));
	}
}

package com.streamchat;

import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.BeforeClass;
import org.junit.Test;

public class StreamChatOverlayTest
{
	private static FontMetrics metrics;

	@BeforeClass
	public static void setUp()
	{
		final BufferedImage image = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		metrics = g.getFontMetrics();
		g.dispose();
	}

	@Test
	public void shortTextStaysOnOneLine()
	{
		final List<String> lines = StreamChatOverlay.wrap("hi", metrics, 400);

		assertEquals(1, lines.size());
		assertEquals("hi", lines.get(0));
	}

	@Test
	public void wrapsOnWordBoundaries()
	{
		final String text = "the quick brown fox jumps over the lazy dog again and again";
		final int width = 80;

		final List<String> lines = StreamChatOverlay.wrap(text, metrics, width);

		assertTrue("expected multiple lines, got " + lines, lines.size() > 1);
		for (String line : lines)
		{
			assertTrue("line too wide: " + line, metrics.stringWidth(line) <= width);
		}
		// No text is lost or duplicated.
		assertEquals(text, String.join(" ", lines));
	}

	@Test
	public void hardBreaksAWordWiderThanThePanel()
	{
		// A single unbroken token (a pasted link, or keyboard mashing) cannot be wrapped on spaces,
		// so it has to be split mid-word rather than overflowing the panel.
		final String text = repeat("A", 200);

		final List<String> lines = StreamChatOverlay.wrap(text, metrics, 60);

		assertTrue(lines.size() > 1);
		for (String line : lines)
		{
			assertTrue("line too wide: " + line, metrics.stringWidth(line) <= 60);
		}
		assertEquals(text, String.join("", lines));
	}

	@Test
	public void handlesEmptyAndSpacesOnly()
	{
		assertTrue(StreamChatOverlay.wrap("", metrics, 100).isEmpty());
		assertTrue(StreamChatOverlay.wrap("   ", metrics, 100).isEmpty());
	}

	@Test
	public void collapsesRunsOfSpaces()
	{
		final List<String> lines = StreamChatOverlay.wrap("a    b", metrics, 400);

		assertEquals(1, lines.size());
		assertEquals("a b", lines.get(0));
	}

	private static String repeat(String s, int n)
	{
		final StringBuilder sb = new StringBuilder(s.length() * n);
		for (int i = 0; i < n; i++)
		{
			sb.append(s);
		}
		return sb.toString();
	}
}

