package com.streamchat.twitch;

import java.awt.Color;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class IrcMessageTest
{
	@Test
	public void parsesTaggedPrivmsg()
	{
		final String line = "@badge-info=;badges=broadcaster/1;color=#1E90FF;display-name=SomeUser;"
			+ "emotes=;id=abc-123;mod=0 :someuser!someuser@someuser.tmi.twitch.tv PRIVMSG #channel :hello world";

		final IrcMessage msg = IrcMessage.parse(line);

		assertEquals("PRIVMSG", msg.getCommand());
		assertEquals("someuser", msg.nick());
		assertEquals("#channel", msg.param(0));
		assertEquals("hello world", msg.trailing());
		assertEquals("SomeUser", msg.tag("display-name"));
		assertEquals("abc-123", msg.tag("id"));
		assertEquals("#1E90FF", msg.tag("color"));
	}

	@Test
	public void emptyTagsReadAsNull()
	{
		// Twitch sends the key with no value rather than omitting it for users with no colour set.
		final IrcMessage msg = IrcMessage.parse("@color=;id=x :a!a@a PRIVMSG #c :hi");

		assertNull(msg.tag("color"));
		assertEquals("x", msg.tag("id"));
	}

	@Test
	public void parsesPingWithoutPrefix()
	{
		final IrcMessage msg = IrcMessage.parse("PING :tmi.twitch.tv");

		assertEquals("PING", msg.getCommand());
		assertNull(msg.getPrefix());
		assertEquals("tmi.twitch.tv", msg.trailing());
	}

	@Test
	public void trailingKeepsColonsAndSpaces()
	{
		final IrcMessage msg = IrcMessage.parse(":a!a@a PRIVMSG #c :check this: http://example.com/a b");

		assertEquals("check this: http://example.com/a b", msg.trailing());
	}

	@Test
	public void unescapesTagValues()
	{
		// \s space, \: semicolon, \\ backslash, per the IRCv3 message-tags spec.
		assertEquals("a b", IrcMessage.unescapeTagValue("a\\sb"));
		assertEquals("a;b", IrcMessage.unescapeTagValue("a\\:b"));
		assertEquals("a\\b", IrcMessage.unescapeTagValue("a\\\\b"));
		assertEquals("SomeUser subscribed for 3 months!",
			IrcMessage.unescapeTagValue("SomeUser\\ssubscribed\\sfor\\s3\\smonths!"));
	}

	@Test
	public void unescapeDropsLoneTrailingBackslash()
	{
		assertEquals("ab", IrcMessage.unescapeTagValue("ab\\"));
	}

	@Test
	public void handlesCrLfAndBlankLines()
	{
		assertNull(IrcMessage.parse(""));
		assertNull(IrcMessage.parse("   "));
		assertNull(IrcMessage.parse(null));

		final IrcMessage msg = IrcMessage.parse("PING :x\r\n");
		assertEquals("PING", msg.getCommand());
		assertEquals("x", msg.trailing());
	}

	@Test
	public void parsesNumericWelcome()
	{
		final IrcMessage msg = IrcMessage.parse(":tmi.twitch.tv 001 justinfan12345 :Welcome, GLHF!");

		assertEquals("001", msg.getCommand());
		assertEquals("justinfan12345", msg.param(0));
	}

	@Test
	public void parsesColors()
	{
		assertEquals(new Color(0x1E90FF), TwitchChatSource.parseColor("#1E90FF"));
		assertNull(TwitchChatSource.parseColor(null));
		assertNull(TwitchChatSource.parseColor(""));
		assertNull(TwitchChatSource.parseColor("1E90FF"));
		assertNull(TwitchChatSource.parseColor("#GGGGGG"));
	}

	@Test
	public void parsesUserNoticeSystemMessage()
	{
		final String line = "@msg-id=resub;system-msg=SomeUser\\ssubscribed\\sfor\\s3\\smonths!;id=n1 "
			+ ":tmi.twitch.tv USERNOTICE #channel :great stream";

		final IrcMessage msg = IrcMessage.parse(line);

		assertEquals("USERNOTICE", msg.getCommand());
		assertEquals("SomeUser subscribed for 3 months!", msg.tag("system-msg"));
		assertTrue(msg.getTags().containsKey("msg-id"));
	}
}

package com.streamchat.twitch;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class TwitchEmoteOnlyTest
{
	@Test
	public void singleEmoteOnly()
	{
		// "Kappa" is chars 0-4, and that is the whole message.
		assertTrue(TwitchChatSource.isEmoteOnly("Kappa", "25:0-4"));
	}

	@Test
	public void severalEmotesAndNothingElse()
	{
		assertTrue(TwitchChatSource.isEmoteOnly("Kappa Kappa", "25:0-4,6-10"));
		assertTrue(TwitchChatSource.isEmoteOnly("Kappa PogChamp", "25:0-4/88:6-13"));
	}

	@Test
	public void emoteWithRealWordsIsNotEmoteOnly()
	{
		assertFalse(TwitchChatSource.isEmoteOnly("lol Kappa", "25:4-8"));
		assertFalse(TwitchChatSource.isEmoteOnly("Kappa nice", "25:0-4"));
	}

	@Test
	public void plainTextIsNotEmoteOnly()
	{
		assertFalse(TwitchChatSource.isEmoteOnly("hello there", ""));
		assertFalse(TwitchChatSource.isEmoteOnly("hello there", null));
	}

	@Test
	public void thirdPartyEmotesAreTreatedAsText()
	{
		// BTTV/7TV emotes never appear in the emotes tag, so this must not be hidden -- erring
		// towards showing a message rather than silently dropping one.
		assertFalse(TwitchChatSource.isEmoteOnly("catJAM", ""));
	}

	@Test
	public void malformedTagDoesNotHide()
	{
		assertFalse(TwitchChatSource.isEmoteOnly("Kappa", "25:notanumber"));
		assertFalse(TwitchChatSource.isEmoteOnly("Kappa", "25"));
	}

	@Test
	public void outOfBoundsRangeIsClamped()
	{
		// Twitch indexes by code point, so a message with surrogate pairs can report a range past
		// the end. That must not throw.
		assertTrue(TwitchChatSource.isEmoteOnly("Kappa", "25:0-999"));
	}

	@Test
	public void emptyMessage()
	{
		assertFalse(TwitchChatSource.isEmoteOnly("", "25:0-4"));
		assertFalse(TwitchChatSource.isEmoteOnly(null, "25:0-4"));
	}
}

package com.streamchat.twitch;

import com.streamchat.StreamEventType;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class TwitchEventTest
{
	@Test
	public void subVariantsAreSubscriptions()
	{
		assertEquals(StreamEventType.SUBSCRIPTION, TwitchChatSource.classifyUserNotice("sub"));
		assertEquals(StreamEventType.SUBSCRIPTION, TwitchChatSource.classifyUserNotice("resub"));
		assertEquals(StreamEventType.SUBSCRIPTION, TwitchChatSource.classifyUserNotice("primepaidupgrade"));
	}

	@Test
	public void giftVariantsAreGifts()
	{
		assertEquals(StreamEventType.GIFT, TwitchChatSource.classifyUserNotice("subgift"));
		assertEquals(StreamEventType.GIFT, TwitchChatSource.classifyUserNotice("anonsubgift"));
		assertEquals(StreamEventType.GIFT, TwitchChatSource.classifyUserNotice("submysterygift"));
	}

	@Test
	public void raidIsARaid()
	{
		assertEquals(StreamEventType.RAID, TwitchChatSource.classifyUserNotice("raid"));
	}

	@Test
	public void unknownNoticesStillCountAsEvents()
	{
		// Twitch adds msg-ids over time; an unrecognised one should still be shown, not dropped.
		assertEquals(StreamEventType.OTHER, TwitchChatSource.classifyUserNotice("somethingnew"));
		assertEquals(StreamEventType.OTHER, TwitchChatSource.classifyUserNotice(null));
	}
}

package com.streamchat.youtube;

import com.streamchat.StreamEventType;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class YouTubeEventTest
{
	@Test
	public void membershipsAndSuperChatsAreEvents()
	{
		assertEquals(StreamEventType.SUBSCRIPTION, YouTubeChatSource.classify("newSponsorEvent"));
		assertEquals(StreamEventType.SUBSCRIPTION, YouTubeChatSource.classify("memberMilestoneChatEvent"));
		assertEquals(StreamEventType.GIFT, YouTubeChatSource.classify("membershipGiftingEvent"));
		assertEquals(StreamEventType.DONATION, YouTubeChatSource.classify("superChatEvent"));
		assertEquals(StreamEventType.DONATION, YouTubeChatSource.classify("superStickerEvent"));
	}

	@Test
	public void detectsCustomEmojiOnlyMessages()
	{
		assertTrue(YouTubeChatSource.isEmoteOnly(":yt_laugh:"));
		assertTrue(YouTubeChatSource.isEmoteOnly(":a: :b:"));
	}

	@Test
	public void messagesWithWordsAreNotEmoteOnly()
	{
		assertFalse(YouTubeChatSource.isEmoteOnly("nice :yt_laugh:"));
		assertFalse(YouTubeChatSource.isEmoteOnly("hello"));
		assertFalse(YouTubeChatSource.isEmoteOnly(""));
		assertFalse(YouTubeChatSource.isEmoteOnly(null));
		// A bare colon-word is not a shortcode.
		assertFalse(YouTubeChatSource.isEmoteOnly("time: 5"));
	}

	@Test
	public void ordinaryChatIsNotAnEvent()
	{
		assertNull(YouTubeChatSource.classify("textMessageEvent"));
		assertNull(YouTubeChatSource.classify(null));
		assertNull(YouTubeChatSource.classify("somethingUnknown"));
	}
}

package com.streamchat.youtube;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class YouTubeTargetTest
{
	@Test
	public void parsesBareVideoId()
	{
		final YouTubeTarget t = YouTubeTarget.parse("dQw4w9WgXcQ");

		assertEquals(YouTubeTarget.Kind.VIDEO, t.getKind());
		assertEquals("dQw4w9WgXcQ", t.getValue());
		assertFalse(t.isExpensiveToResolve());
	}

	@Test
	public void parsesWatchUrl()
	{
		assertEquals("dQw4w9WgXcQ",
			YouTubeTarget.parse("https://www.youtube.com/watch?v=dQw4w9WgXcQ").getValue());
		assertEquals("dQw4w9WgXcQ",
			YouTubeTarget.parse("https://www.youtube.com/watch?list=x&v=dQw4w9WgXcQ").getValue());
	}

	@Test
	public void parsesLiveAndShortUrls()
	{
		assertEquals("dQw4w9WgXcQ", YouTubeTarget.parse("https://youtu.be/dQw4w9WgXcQ").getValue());
		assertEquals("dQw4w9WgXcQ",
			YouTubeTarget.parse("https://www.youtube.com/live/dQw4w9WgXcQ").getValue());
	}

	@Test
	public void parsesChannelId()
	{
		final YouTubeTarget t = YouTubeTarget.parse("UC_x5XG1OV2P6uZZ5FSM9Ttw");

		assertEquals(YouTubeTarget.Kind.CHANNEL_ID, t.getKind());
		assertTrue(t.isExpensiveToResolve());
	}

	@Test
	public void parsesHandle()
	{
		final YouTubeTarget t = YouTubeTarget.parse("@SomeCreator");

		assertEquals(YouTubeTarget.Kind.HANDLE, t.getKind());
		assertEquals("SomeCreator", t.getValue());
		assertTrue(t.isExpensiveToResolve());

		assertEquals("SomeCreator", YouTubeTarget.parse("https://youtube.com/@SomeCreator").getValue());
	}

	@Test
	public void channelIdIsNotMistakenForAVideoId()
	{
		// Both are made of the same character class, so length is what separates them.
		final YouTubeTarget t = YouTubeTarget.parse("https://www.youtube.com/channel/UC_x5XG1OV2P6uZZ5FSM9Ttw");

		assertEquals(YouTubeTarget.Kind.CHANNEL_ID, t.getKind());
		assertEquals("UC_x5XG1OV2P6uZZ5FSM9Ttw", t.getValue());
	}

	@Test
	public void rejectsJunk()
	{
		assertNull(YouTubeTarget.parse(null));
		assertNull(YouTubeTarget.parse(""));
		assertNull(YouTubeTarget.parse("   "));
		assertNull(YouTubeTarget.parse("not a valid id"));
		assertNull(YouTubeTarget.parse("https://www.youtube.com/results?search_query=x"));
	}

	@Test
	public void trimsSurroundingWhitespace()
	{
		assertEquals("dQw4w9WgXcQ", YouTubeTarget.parse("  dQw4w9WgXcQ  ").getValue());
	}
}
